/* GSTF : liste des nouveautés, chargée à la demande */
function nouveautesTout(){return[{v:569,d:"2026-11-27",l:["Actes du symposium › Contributions : le champ « Question posée (programme) » devient une grande zone de texte (plusieurs lignes) ; un texte long de plusieurs paragraphes peut enfin être lu en entier et corrigé sans que les paragraphes soient collés."]},{v:568,d:"2026-11-27",l:["Dépliant d’invitation (programme) : le « mot d’invitation » s’imprime au volet du milieu, sous la date et le lieu ; le code QR est placé à côté de sa légende pour faire de la place ; lignes équilibrées dans l’encadré « Sur invitation », le titre et les titres des contributions (plus de mot isolé sur la dernière ligne)."]},{v:567,d:"2026-11-27",l:["Dépliant d’invitation (programme) : typographie française — espace insécable avant « ; : ? ! » » et après « « » (plus de guillemet seul en début de ligne), apostrophes courbes (’) partout ; « Sainte Thérèse de l’Enfant-Jésus » écrit en entier dans l’adresse."]},{v:566,d:"2026-11-27",l:["Dépliant d’invitation (programme) : le dernier jour (samedi) commence en haut de la 3e colonne ; un paragraphe n’est plus coupé entre deux colonnes ; la prière s’imprime à la fin du programme (et non plus au volet du milieu, où elle cachait l’adresse) ; un titre de prière en MAJUSCULES est mis en valeur ; « Amen. » n’est plus poussé à droite."]},{v:565,d:"2026-11-27",l:["Dépliant d’invitation (programme) : les informations pratiques et la prière s’impriment aussi dans ce modèle (volet du milieu, sous le code QR) ; le code QR ouvre l’Agenda au mois du symposium ; « Faliarivo – Ambanidia » avec le tiret long dans l’adresse."]},{v:564,d:"2026-11-27",l:["Actes du symposium › Fabriquer : nouveau format « 📱 Image pour WhatsApp et Facebook » (image verticale 1080 × 1350 avec photo, titre, dates, lieu et code QR vers l’Agenda), à télécharger puis à partager."]},{v:563,d:"2026-11-27",l:["Dépliant du symposium : la photo de chaque intervenant (bouton « 📷 Photo de l’intervenant » de sa contribution) s’affiche en petit rond à côté de son nom, dans « Les intervenants » (pliage en trois) ; sans photo, ses initiales s’affichent dans le rond."]},{v:562,d:"2026-11-27",l:["Dépliant du symposium : le code QR ouvre directement l’Agenda au mois du symposium (champ « Date du symposium »), avec la mention « Programme et inscription : scannez ce code »."]},{v:561,d:"2026-11-27",l:["Dépliant du symposium : trois champs de plus dans « 1. Couverture » : mot d’invitation (au dos), prière ou citation (sous les informations pratiques) et légende sous la photo de couverture."]},{v:560,d:"2026-11-27",l:["Dépliant du symposium : couverture entièrement centrée, sous-titre plus grand, date et lieu sur deux lignes ; sous chaque intervention, seul le nom de l’intervenant reste (sa fonction est dans « Les intervenants »)."]},{v:559,d:"2026-11-27",l:["Dépliant du symposium : deux champs réservés au dépliant dans « Actes du symposium › 1. Couverture » (mention de couverture et informations pratiques), qui ne touchent plus au livret des Actes ; les informations pratiques s’impriment à l’intérieur (volet de droite en pliage en trois) ; en pliage en deux, programme et intervenants à gauche, interventions à droite."]},{v:558,d:"2026-11-27",l:["Lecteur des PDF, mode Texte : bouton « 🔊 Écouter ». Le téléphone lit le texte à voix haute en français, paragraphe après paragraphe, puis passe à la page suivante (selon les voix installées sur le téléphone)."]},{v:557,d:"2026-11-27",l:["Lecteur des PDF, mode Texte : bouton de fond Clair, Sépia ou Sombre, retenu pour la prochaine fois."]},{v:556,d:"2026-11-27",l:["Lecteur des PDF : toucher le numéro de page (ex. « 5 / 60 ») pour aller directement à une page ; en mode Texte, glisser le doigt vers la gauche ou la droite pour changer de page."]},{v:555,d:"2026-11-27",l:["Lecteur des PDF : le téléphone retient la dernière page lue de chaque document et propose « Reprendre à la page … »."]},{v:554,d:"2026-11-27",l:["Lecteur des PDF : nouveau mode « Aa Texte ». Les boutons − et + agrandissent les lettres et le texte se remet à la largeur du téléphone ; le bouton « 📄 Page » montre la page telle qu’elle est imprimée. Les pages scannées restent affichées comme image."]},{v:553,d:"2026-11-27",l:["Mise à jour des téléphones : la page indiquait encore l’ancien code du site (v551) ; les téléphones et l’application installée reçoivent de nouveau chaque nouvelle version."]},{v:552,d:"2026-11-27",l:["Affiliation à l’UCM (décision du Préfet) : l’année d’affiliation n’est plus écrite, ni sur la page « Le Séminaire », ni dans l’Aide, ni sur les relevés de notes."]},{v:551,d:"2026-11-26",l:["Pages des PDF : un grand bouton « 🔍 Lire les pages en grand » et « 🔍 Agrandir » sur chaque page ; la page s’ouvre directement à la taille de lecture (aussi pour les articles payants)."]},{v:550,d:"2026-11-26",l:["Trois petites mises en forme manquaient (espacements dans quelques écrans de l’administration) : rétablies."]},{v:549,d:"2026-11-26",l:["Cartes du personnel et des enseignants : le NOM en gras puis les prénoms, de la même taille sur toutes les cartes ; photo plus grande ; en bas « Carte personnelle · trouvée ? … » ; au dos : à présenter, ne pas prêter, à rendre en quittant le Séminaire. Cartes d’étudiants : le nom de la même taille sur toutes les cartes ; signature et cachet un peu plus grands."]},{v:548,d:"2026-11-26",l:["« 📄 Lire le PDF ici » : touchez une page pour l’ouvrir en plein écran ; agrandissez avec deux doigts (ou ＋ / −), glissez pour vous déplacer, ‹ › pour changer de page."]},{v:547,d:"2026-11-26",l:["Articles, sur le téléphone : un titre long ne déborde plus de la petite couverture dessinée (les mots se coupent, la taille s’adapte)."]},{v:546,d:"2026-11-26",l:["Cartes du personnel et des enseignants : « Valable jusqu’au » se règle sur la page des cartes (imprimées et sur le téléphone) ; « 📷 Déposer plusieurs photos » range chaque photo chez la personne dont le NOM est dans le nom du fichier."]},{v:545,d:"2026-11-26",l:["Carte du personnel sur le téléphone (en bas du site : « Carte du personnel ») : la première fois, le numéro de téléphone inscrit dans le site et un code de 4 chiffres donné par le secrétariat ; ensuite le téléphone se souvient. Il faut le SQL 203."]},{v:544,d:"2026-11-26",l:["Cartes › Personnel : la liste du personnel qui n’a pas de fiche Enseignant (cuisine, chauffeur, jardin, entretien, bibliothèque) : nom, fonction, téléphone (jamais sur la carte), photo d’identité ; leur carte se fait avec les autres. Les cartes des enseignants et du personnel n’ont plus de signature ni d’année dans la bande, et sont valables jusqu’au 30 juin. Il faut le SQL 201."]},{v:543,d:"2026-11-26",l:["Couverture des actes et dépliant d’invitation : téléphone, courriel et site alignés (les icônes l’une sous l’autre, le bloc centré).","Actes du symposium : chaque contribution a une « Biographie de l’intervenant » à côté de sa photo ; le livret (impression et Word) a une section « Les intervenants » avec la photo, le nom, la fonction et la biographie de chacun."]},{v:542,d:"2026-11-26",l:["Actes du symposium › « Fabriquer » › « 🎟 Dépliant d’invitation (programme) » : le dépliant d’invitation au modèle du Grand Séminaire (cadre pêche, titres rouges, logo et sainte Thérèse), rempli tout seul depuis le programme : couverture, objectif, intervenants, programme jour par jour, qui est invité, contacts et code QR de l’Agenda."]},{v:541,d:"2026-11-26",l:["Relevés des anciens : « NÉ LE … à … » sous le nom, d’après les archives (candidats au baccalauréat 2017-2022, liste 2016-2017, cartes d’étudiant 2011-2012) : 420 anciens. Il faut le SQL 200."]},{v:540,d:"2026-11-26",l:["Relevés des anciens de 2011-2012 : les archives n’ont que le 1er semestre ; le relevé ne montre plus de total ni de moyenne (la « moyenne » du fichier était fausse) et porte la mention « Archives incomplètes ». Il faut le SQL 199."]},{v:539,d:"2026-11-26",l:["« Mémoire du Séminaire » : les archives du Séminaire année par année (livrets, fêtes, célébrations, photos), avec recherche ; l’administration y voit aussi les archives réservées et ajoute, valide ou retire les documents. Lien dans le pied de page et dans « Anciens du Séminaire ». Il faut le SQL 197."]},{v:538,d:"2026-11-26",l:["Cartes des enseignants et du personnel : Administration › Cartes › « 👔 Enseignants et personnel » (nom avec le titre, fonction, numéro de carte, QR code pour la vérification et la bibliothèque, signature du Préfet des études). Il faut le SQL 193."]},{v:537,d:"2026-11-25",l:["Le Séminaire est présenté partout comme « Studium affilié à l’UCM · Licence (diplôme d’État malgache) » : pied de page, accueil, page « Le Séminaire », description pour Google et Aide."]},{v:536,d:"2026-11-25",l:["Bibliothèque (gestion) : en haut, « 🔎 Chercher un livre à prêter ou à modifier » : la recherche ouvre les résultats avec les boutons « Prêter » et « Modifier »."]},{v:535,d:"2026-11-25",l:["Bibliothèque (gestion) : les onglets rangés en 4 groupes (Prêts, Catalogue, En ligne, Suivi) ; les liens qui ne s’ouvrent plus bien visibles, avec un bouton qui ne montre qu’eux ; les outils du lecteur cachés pendant la gestion.","Sur ordinateur, les boutons ronds (remonter, Aide) ne cachent plus les boutons des pages."]},{v:534,d:"2026-11-25",l:["Le bandeau « Le site s’ouvre maintenant sur votre espace » disparaît dès qu’on ouvre un autre onglet ou une autre page."]},{v:533,d:"2026-11-25",l:["Administration : une case « Chercher une page » en haut du menu (fautes et mots proches acceptés : « bulletin » trouve « Relevés de notes »), les pages « Souvent ouvertes » sur cet appareil (et ☆ pour en épingler), des groupes qui se replient, et Ctrl + K pour chercher depuis tout le site."]},{v:532,d:"2026-11-25",l:["État du site : la date de la dernière sauvegarde sur le Drive (rouge après 36 heures), un rappel quand l’essai de restauration a plus de 6 mois, et la marche à suivre si la base est en pause."]},{v:531,d:"2026-11-25",l:["Téléphones : le bouton « ? » de l’Aide devient un petit onglet collé au bord droit, qui ne cache plus le texte."]},{v:530,d:"2026-11-25",l:["Mise à jour plus sûre : avant de garder un fichier du site, le téléphone vérifie qu’il correspond exactement à la nouvelle version ; sinon, il le redemande plus tard."]},{v:529,d:"2026-11-25",l:["État du site : « Restauration testée » indique l’essai complet du 25 novembre (structure et données)."]},{v:528,d:"2026-11-25",l:["Sauvegarde : le fichier de restauration peut être relancé sans jamais créer de doublon, même dans les tables d’archives (essai complet du 25 novembre avec la vraie sauvegarde)."]},{v:527,d:"2026-11-25",l:["« Test réel » : il vérifie aussi les relevés des anciens, les dates de proclamation, les cartes perdues et le journal des photos de cartes."]},{v:526,d:"2026-11-25",l:["Vitesse : le portail des personnes connectées (notes, devoirs, entretiens…) se charge à part, juste après la connexion : les visiteurs ne le téléchargent plus.","Vitesse : un étudiant ne télécharge plus l’espace du personnel (477 Ko), sauf s’il est responsable d’un groupe."]},{v:525,d:"2026-11-25",l:["Carte d’étudiant (décision du Préfet) : au dos, « Cette carte est rigoureusement personnelle. Elle ne doit pas être prêtée. »"]},{v:524,d:"2026-11-25",l:["Vitesse : les modes d’emploi de l’Administration (32 Ko) arrivent avec l’Aide et ne sont plus téléchargés par les visiteurs."]},{v:523,d:"2026-11-25",l:["Vitesse : les tournures de phrases que « Aide » reconnaît (30 Ko) arrivent avec l’Aide, quand on l’ouvre, et non plus à l’ouverture du site."]},{v:522,d:"2026-11-25",l:["Vitesse : la bibliothèque, l’agenda et les articles se chargent maintenant à part, quand on ouvre leur onglet : le code téléchargé par chaque visiteur à l’ouverture du site passe de 440 à 410 Ko environ."]},{v:521,d:"2026-11-25",l:["Relevés de notes aux normes internationales (décision du Préfet) : établissement affilié à l’UCM, diplôme préparé (Licence, diplôme d’État malgache), date et lieu de naissance, colonne ECTS et crédits obtenus, échelle de notation expliquée en bas de page. Tout tient sur une page. Une case du modèle permet de revenir à l’ancien relevé.","Crédits : nouvelle règle « 3 crédits par cours (25 h minimum) ; TP, symposium et compte rendu de lecture : 3 » (Programme des études)."]},{v:520,d:"2026-11-25",l:["Relevés des anciens : la signature et le cachet s’impriment de nouveau, même quand on ouvre directement « Relevés des anciens » sans passer par « Relevés de notes »."]},{v:519,d:"2026-11-25",l:["Photo de profil (décision du Préfet) : les administrateurs fixent la date jusqu’à laquelle chaque étudiant peut changer lui-même sa photo (Administration › Étudiants › « 📷 Photos de profil »). Première date : 21 décembre 2026. Ensuite, c’est l’administration qui la change ; carte déjà imprimée : le Préfet seul, comme avant."]},{v:518,d:"2026-11-25",l:["Vitesse : un visiteur ne télécharge plus jamais l’espace du personnel (477 Ko). Avant, il le recevait en ouvrant « Soutenir le Séminaire », « Administration », la connexion du personnel ou « Annales ».","Une partie du code réservé à l’administration (relevés des anciens, examens, rôles, listes de classe) quitte aussi le code de base."]},{v:517,d:"2026-11-25",l:["Vitesse : « État du site » affiche les trois objectifs de vitesse (code de base, page visible en 3G, pages de l’Administration en 3G) et le temps d’ouverture de chaque page de l’Administration (SQL 188)."]},{v:516,d:"2026-11-25",l:["Vitesse : « État du site » s’ouvre sur le résumé ; la vitesse, le contrôle de « Aide » et les signalements se chargent avec le bouton « Lancer les vérifications détaillées ».","Connexion un peu plus rapide : le profil et les rôles sont demandés en même temps."]},{v:515,d:"2026-11-25",l:["Vitesse : la mise en forme du site est maintenant dans un fichier à part (site.css), gardé sur le téléphone d’une version à l’autre. Sur GitHub, déposez toujours tous les fichiers ensemble : index.html, app.js et site.css."]},{v:514,d:"2026-11-25",l:["Vitesse : l’Aide et la liste des nouveautés ne sont plus téléchargées d’avance chez ceux qui ne les ouvrent jamais, et les pages du Séminaire ne sont relues que si elles ont changé."]},{v:513,d:"2026-11-25",l:["Vitesse : chaque fichier du site a maintenant sa propre empreinte. Un téléphone ne retélécharge plus que les fichiers qui ont vraiment changé."]},{v:512,d:"2026-11-25",l:["Relevés des anciens : le site lit aussi les relevés récents (2015 à 2026 : « CLASSE : PREMIÈRE ANNÉE » en toutes lettres, feuille de synthèse « Sythèse » écartée) ; un relevé établi après la fin de l’année (octobre) n’est plus signalé."]},{v:511,d:"2026-11-25",l:["Notes (décision du Préfet, SQL 186) : seule l’administration voit les notes de tous les étudiants ; chaque étudiant voit les siennes, chaque professeur celles de ses cours ; les éducateurs et les responsables de foyer seulement après la proclamation des résultats du semestre (nouvelle date dans Relevés de notes)."]},{v:510,d:"2026-11-25",l:["Relevés (pour l’uniformité, décision du Préfet) : les notes de l’examen de fin de cycle s’écrivent comme celles du tableau (16,5 et non 16,50), et le nom du signataire tient toujours sur une ligne."]},{v:509,d:"2026-11-25",l:["Relevés des anciens › « Retrouver un ancien » : les mots peuvent être tapés dans n’importe quel ordre, avec une petite faute ; un message clair si rien n’est encore enregistré."]},{v:508,d:"2026-11-25",l:["Deuxième code (décision du Préfet des études) : obligatoire pour l’administration à partir du 1er décembre 2027 ; la base applique de nouveau cette règle (SQL 184)."]},{v:507,d:"2026-11-25",l:["État du site › Aide : les chiffres de l’examen de cette version (et non plus de la version 406), la baisse d’une question du contrôle expliquée, et la mesure extérieure (série cachée de notre ami) avec sa date ; une nouvelle mesure se note en un clic."]},{v:506,d:"2026-11-25",l:["Relevés des anciens : impression au modèle actuel (décision du Préfet), avec « Relevé établi d’après les archives », le cycle et le matricule, la moyenne du bulletin d’origine, l’examen de fin de cycle, et le code QR de vérification."]},{v:505,d:"2026-11-25",l:["Administration › « Relevés des anciens » (SQL 183) : les bulletins Excel des archives (depuis 1999) sont lus par le site et contrôlés (somme des notes, total, moyenne, doublons) ; l’administration vérifie, puis enregistre ; matricule GSTF-année d’entrée-numéro pour chaque ancien. Administration seulement, aucune coordonnée."]},{v:504,d:"2026-11-25",l:["Relevé des notes (décision du Préfet) : le matricule s’imprime sous le numéro (« N° matricule : GSTF-2024-092 »)."]},{v:503,d:"2026-11-25",l:["Carte d’étudiant (décision du Préfet, pour l’uniformité) : la date de validité en chiffres, « Valable jusqu’au 30/09/2027 »."]},{v:502,d:"2026-11-25",l:["Cartes d’étudiant (SQL 182) : le secrétariat coche « Validée » après avoir vérifié la photo et la naissance (si l’étudiant les change, la case se décoche) ; « Carte perdue » donne un nouveau QR code et l’ancienne carte affiche « non valide » ; à la vérification d’une carte, le personnel connecté voit aussi la photo enregistrée."]},{v:501,d:"2026-11-25",l:["Carte d’étudiant imprimée par l’étudiant lui-même : « COPIE PERSONNELLE », sans signature ni cachet."]},{v:500,d:"2026-11-25",l:["Cartes d’étudiant : traits de coupe aux coins ; dos de la carte (carte personnelle, adresse et téléphone du Séminaire, bibliothèque et examens, vérification par le QR code) ; impression recto-verso."]},{v:499,d:"2026-11-25",l:["Carte d’étudiant : QR code plus robuste (correction « M », marge blanche plus large) ; la signature et le cachet sous le QR code, jamais dessus ; « Le Préfet des études » plus lisible."]},{v:498,d:"2026-11-25",l:["Carte d’étudiant (décisions du Préfet) : « Promotion 2024-2027 » et « Valable jusqu’au 30 septembre 2027 », selon le vrai parcours pour un redoublant ; pas de ligne « Né le » sans la date ; le lieu de naissance sur 2 lignes au plus."]},{v:497,d:"2026-11-25",l:["Cartes d’étudiant (décision du Préfet des études) : dès que l’administration imprime la carte d’un étudiant, sa photo est fixée (🔒) ; seul le Préfet peut encore la changer, et chaque changement est noté (SQL 181)."]},{v:496,d:"2026-11-25",l:["Carte d’étudiant (décision du Préfet des études) : elle sert pour toutes les années, donc la classe n’y est plus écrite ; la ligne devient « N° matricule : GSTF-2026-001 »."]},{v:495,d:"2026-11-25",l:["Matricule définitif des étudiants (décision du Préfet des études) : GSTF-année d’entrée-numéro de la fiche de présence de la 1re année, par exemple GSTF-2026-014. Donné automatiquement à tous (anciens compris) et à chaque nouvel inscrit ; il ne change jamais. Sur la carte d’étudiant, l’attestation, la vérification du QR code et la liste de l’économat ; se corrige dans Cartes d’étudiant. Le numéro de classe (« Numéro : 108 ») reste sur les fiches et les relevés.","Contrôle des données : un même numéro de fiche dans deux classes différentes n’est plus signalé comme un doublon."]},{v:494,d:"2026-11-25",l:["Téléphone : la fenêtre « Saint du jour » (et les autres fenêtres) reste dans l’écran, collée à 8 px des bords."]},{v:493,d:"2026-11-24",l:["Grand oral (décision du Préfet des études) : seule la saisie des 16 examinateurs reste à faire ; le site enregistre, répartit les étudiants au hasard, fait le planning, écrit les examinateurs dans la fiche et tire les questions tout seul. Les réglages sont rangés dans « ⚙️ Réglages »."]},{v:492,d:"2026-11-24",l:["Grand oral : le programme garde la même forme mais change en février ; le site dit quand il a été mis à jour et rappelle de le remplacer tant qu’il date d’avant février."]},{v:491,d:"2026-11-24",l:["Grand oral : les 4 catégories du programme (Écriture sainte, Dogmatique, Morale, Pastorale), 4 salles et 4 jurys de 4 examinateurs, le planning de passage (15 min, à partir de 8 h), les convocations des étudiants et le tirage au sort d’une question par catégorie (gardé sur l’ordinateur de l’administration)."]},{v:490,d:"2026-11-24",l:["Hors connexion : les 5 derniers articles publics lus restent lisibles sans Internet."]},{v:489,d:"2026-11-24",l:["Prières : « Année A, paire » s’écrit dans la couleur du texte, bien lisible."]},{v:488,d:"2026-11-24",l:["Aide : elle comprend mieux le sens (évêché = diocèse ; recension, résumé critique = compte rendu de lecture ; enseignant invité = enseignant…), ignore les petits mots (« ils »), ne change plus un mot juste en un autre (« président »), ne montre « Pour aller plus loin » que si le lien a un rapport, et dit au visiteur que le contrôle des données est réservé à l’administration."]},{v:487,d:"2026-11-24",l:["Aide : la fiche du compte rendu de lecture donne les sept étapes de travail (lire, prendre des notes, résumer, analyser, rapprocher, juger, rédiger)."]},{v:486,d:"2026-11-24",l:["Aide : un malade, un blessé, un accident ou une urgence la nuit ouvre une fiche pratique « 🚑 Urgence médicale ou accident » : réveiller tout de suite le gardien du Séminaire (décision du Préfet des études) ; la fiche de détresse reste pour les autres cas."]},{v:485,d:"2026-11-24",l:["Calendrier (décision du Préfet des études) : le 2e semestre finit le 18 juin 2027 ; « 8 février » sans zéro ; la page publique du calendrier (celle que Google montre) écrit « 1er avril » et met le symposium entre les deux semestres."]},{v:484,d:"2026-11-24",l:["Téléphone : la page de l’Administration ne devient plus plus large que l’écran (un texte caché de la v471 la poussait à droite) ; les fenêtres (saint du jour, lectures, aide…) restent entières dans l’écran."]},{v:483,d:"2026-11-24",l:["Fiches des examinateurs : le site lit aussi la note écrite à la main (« 14,5 », un chiffre par case) ; cases noircies et écriture se contrôlent l’une l’autre, et ce qui n’est pas sûr est signalé en jaune."]},{v:482,d:"2026-11-24",l:["Examen de fin de cycle : « 🖨 Fiches des examinateurs (à scanner) » : une fiche par examinateur, avec ses étudiants et des cases à noircir ; après l’examen, « 📷 Lire les fiches scannées » place toutes les notes d’un coup."]},{v:481,d:"2026-11-24",l:["Examen de fin de cycle : les notes des oraux et de l’écrit se remplissent sans tout taper : « 📄 Lire les notes » (photo de la fiche du jury, PDF, Word, Excel) ou « 📋 Coller depuis Excel » ; « Entrée » passe à l’étudiant suivant."]},{v:480,d:"2026-11-24",l:["Relevés : la ligne « Mention » sous la moyenne n’apparaît que si la case « Mention » est cochée dans les colonnes du modèle (comme l’ancien relevé, sans mention)."]},{v:479,d:"2026-11-24",l:["Relevés, fiches de présence, liste de classe, fiches de notes et attestation de scolarité (décision du Préfet des études) : « Numéro : 108 », comme avant, au lieu de « N° matricule » ; partout le même numéro, celui de l’étudiant."]},{v:478,d:"2026-11-24",l:["Relevé de la 3e année (décision du Préfet des études, comme l’ancien relevé) : « Dogmatique spéciale » (à l’ÉCRIT, à la fin) et « Fin du cycle : préparation à l’examen final » ne sont plus dans le tableau des matières ni dans sa moyenne. Réglable dans « 📋 Modèle L3 » (« Matières hors du tableau »)."]},{v:477,d:"2026-11-24",l:["Relevés imprimés par l’administration : le dessin du code QR apparaît bien (il manquait, seul le texte « Authenticité de ce document » s’imprimait) ; un relevé déjà imprimé sans dessin le reçoit à la réimpression."]},{v:476,d:"2026-11-24",l:["Administration › Enseignants et Étudiants : deux boutons par ligne, « Enregistrer » et « Modifier ▾ » (nouveau mot de passe, modifier le nom, retirer, supprimer définitivement…)."]},{v:475,d:"2026-11-24",l:["Aide (administration) : « contrôle des données » cherche les anomalies et les incohérences (matricules, doublons, diocèses, cours sans professeur, emploi du temps…) et dit où corriger ; « quelles modifications ont été faites ? » montre les changements des 14 derniers jours. Lecture seule : rien n’est changé."]},{v:474,d:"2026-11-24",l:["Aide : ce qui est demandé pour le compte rendu de lecture (un ouvrage spécialisé de 250 pages, deux rapprochements dont un document du Magistère ; nombre de pages non fixé)."]},{v:473,d:"2026-11-24",l:["Corps enseignant : Mme Lanto RABEROHOAVY (Français, 1re année) apparaît aussi sur la page publique ; Musique sacrée est au 1er semestre (décision du Préfet des études)."]},{v:472,d:"2026-11-24",l:["Téléphone : le message « Connexion lente » est plus court, arrive plus tôt et se ferme seul après 4 secondes (ou d’un toucher) ; une marge en bas des pages pour que le bouton « ? » ne cache plus la dernière ligne."]},{v:471,d:"2026-11-24",l:["Accessibilité : un or plus foncé pour les textes (étiquettes « Fête », année liturgique…), « Replier » et les jours passés des entretiens mieux lisibles, plus d’en-tête de tableau vide, titres de la page Confidentialité dans l’ordre."]},{v:470,d:"2026-11-24",l:["Calendrier (décisions du Préfet des études) : « Fête patronale et institution des lecteurs et des acolytes » (les ordres mineurs n’existent plus) ; le symposium des 5 et 6 février apparaît entre les deux semestres."]},{v:469,d:"2026-11-24",l:["Dates : le premier jour du mois s’écrit « 1er » partout (« 1er avril 2027 »)."]},{v:468,d:"2026-11-24",l:["Aide : « comment faire un compte rendu de lecture ? » donne la méthode et les étapes ; une urgence (la nuit, un accident, un danger) ouvre la fiche de détresse ; « oecumenisme » = « Œcuménisme » ; le nombre de diocèses, de congrégations, de professeurs et de livres ; l’attestation de scolarité expliquée à l’étudiant non connecté ; la date limite d’inscription."]},{v:467,d:"2026-11-24",l:["Aide : les démarches pour les TP dans le tableau et la moyenne, pour le code QR du relevé et pour le nombre de travaux de chaque classe."]},{v:466,d:"2026-11-24",l:["Travaux pratiques (décision du Préfet des études) : le relevé ne parle que des travaux de l’année (« Travaux de l’année : 2 sur 3 · Reste : … »), sans les années passées. En 2026-2027, toutes les classes font le compte rendu de lecture (L1 4 travaux, L2 4, L3 3) ; ensuite, la L1 seulement (L1 4, L2 3, L3 2)."]},{v:465,d:"2026-11-24",l:["Livret académique et actes du symposium : le format du papier se choisit (A5, A4, B5, 16 × 24 cm, A6) ; le livret plié et le fichier Word suivent ce format."]},{v:464,d:"2026-11-24",l:["Relevés (décision du Préfet des études) : les TP de l’année s’impriment dans le tableau des matières, comme sur l’ancien relevé (« T.P. … », « Symposium », « Compte rendu de lecture »), et comptent dans le TOTAL et la moyenne. Le bloc à part reste possible dans le modèle (« Place des TP »)."]},{v:463,d:"2026-11-24",l:["Relevés : le cadre « code QR (créé à l’impression) » ne s’imprime plus jamais (il apparaissait à côté du code QR du site quand le relevé sortait sans code)."]},{v:462,d:"2026-11-24",l:["Relevés de notes : « 📄 Lire les numéros dans un fichier » — le site lit les matricules dans un fichier Excel, Word, PDF ou une photo de la liste, les place à côté du bon nom, puis vous vérifiez et enregistrez."]},{v:461,d:"2026-11-24",l:["Relevés de notes : imprimer les relevés d’un diocèse ou d’une congrégation (« Diocèse ou congrégation », avec le nombre d’étudiants de chacun), ou de tous, rangés par diocèse et congrégation."]},{v:460,d:"2026-11-24",l:["Relevés : l’administration voit le relevé à tout moment avec la place du code QR, le cachet et la signature ; à l’impression, le site crée un vrai code QR d’authenticité et garde le relevé tel qu’il est imprimé. Si les notes changent, la nouvelle impression reçoit un nouveau code, et la vérification de l’ancien dit « remplacé par une impression plus récente ».","L’étudiant voit son relevé à tout moment, sans code QR, ni cachet, ni signature (décision du Père Préfet). Il faut le fichier SQL 179.","En-tête des relevés : « Année académique 2026-2027 » n’est plus coupé à droite à l’impression."]},{v:459,d:"2026-11-24",l:["Relevés et bulletins : un bloc « Travaux pratiques » pour les 9 travaux des trois ans (un symposium par année, un compte rendu de lecture, 5 TP de matière : 2 dogmatique, 2 Écriture sainte, 1 autre). Les cases sont les mêmes pour tous (4 en L1, 3 en L2, 2 en L3) ; seule la matière choisie change. Sous le tableau, le suivi des trois ans (« Travaux faits : 4 sur 9… Restent… »).","Le site et la base refusent une matière déjà complète, un deuxième symposium la même année ou un deuxième compte rendu. L’administration saisit les cases et les notes sur le relevé de chaque étudiant (aussi les années passées des L2 et L3) ; l’étudiant voit ses cases dans « Mon espace », déclare son sujet et dépose son TP en PDF ; à un mois des examens, l’étudiant et le tableau de bord du Préfet sont prévenus.","Six réglages dans Administration › Année académique (moyenne, coefficient, note minimale, TP non validé, année du compte rendu, redoublants). Il faut le fichier SQL 178. Le compte rendu de lecture n’est plus un cours."]},{v:458,d:"2026-11-24",l:["Sécurité, après le contrôle du 24 novembre : le site refuse de s’afficher dans le cadre d’un autre site (protection contre les clics piégés) ; un lien venu des données (ressource, article, message…) ne peut être qu’une adresse web, un courriel ou un téléphone, jamais du code ; un compte d’administration est déconnecté après 7 jours sans utilisation sur un appareil.","Documents de cours : un visiteur ne voit plus le nom d’une fonction interne dans un message d’erreur (fichier SQL 177)."]},{v:457,d:"2026-11-24",l:["Actes du symposium : « ✓ Relire la langue » sur chaque texte, et sur tout le livret. La relecture se fait sur l’appareil avec le correcteur libre Grammalecte (rien n’est envoyé sur Internet) : orthographe, grammaire, majuscules sans accent (« EGLISE » → « ÉGLISE »), règles d’écriture du GSTF (pape, Eucharistie, Jean-Paul II, Esprit Saint, saint Augustin), titres de documents en italique (*Pastores dabo vobis*), latin en italique, références bibliques ou du Magistère qui n’existent pas (Mt 29, LG 70), dates de pontificats et de conciles, mots répétés, phrases trop longues, anglicismes, titres, notes, renvois de page, citations longues, noms écrits de deux façons dans le livret.","Chaque remarque se coche ; rien ne change sans vous. Les corrections sont notées dans un journal ; « 📄 Corrections pour l’auteur » imprime ses corrections en « avant / après » à faire approuver avant le bon à tirer. « Ignorer partout dans ce livret » et « Ajouter au dictionnaire du Séminaire » évitent les fausses alertes.","Le livret met tout seul la typographie française (apostrophes, espaces fines, points de suspension) ; les photos des actes sont gardées en meilleure qualité, et la vérification signale celles qui seraient floues (moins de 300 points par pouce)."]},{v:456,d:"2026-11-24",l:["Actes du symposium : « ⚡ Déposer les textes et les photos ». On choisit d’un coup les Word des intervenants, la préface et la synthèse, le programme en PowerPoint et les photos : le site lit le programme (thème, sous-titre, dates, objectif, intervenants avec jour, heure, titre et question), relie chaque Word à son intervenant, garde titres, notes, italique, tableaux et images (« Figure 1… »), prend le résumé et les mots-clés s’ils sont écrits, met une photo au dos de la couverture et les autres en annexe.","Puis il montre ce qu’il a rangé et ce qu’il reste à vérifier (texte pas arrivé, nom non trouvé, résumé, légende, autorisation) : le Père Préfet vérifie, puis fabrique."]},{v:455,d:"2026-11-24",l:["Actes du symposium : le « modèle GSTF 2026 », fait sur le livret des actes sur l’intelligence artificielle (6 février 2026). Couverture à part, sur une feuille A4 en largeur : le devant (logo, sainte Thérèse, « ACTES DU SYMPOSIUM SUR … » en rouge, la date, l’image du thème, les intervenants) et le dos (photo du symposium, adresse, téléphone, courriel, site), dans un cadre de couleur.","Intérieur : la préface en page 1 ; chaque intervention sur une nouvelle page, titre en majuscules et nom de l’intervenant ; titres numérotés tout seuls (I.1, I.1.1, I.1.1.1), un chiffre romain par intervention, la synthèse à la fin ; notes numérotées de 1 à la fin du livre ; figures (« Figure 1 : … ») et tableaux ; table des matières détaillée à la fin, avec points de conduite et numéros de page.","Le modèle classique reste au choix ; pages de titre, titres courants et index se cochent."]},{v:454,d:"2026-11-24",l:["Actes du symposium : « 🔎 Vérifier avant de fabriquer », et la même vérification toute seule avant « Fabriquer » : autorisation signée ou bon à tirer manquant (le livret définitif est alors bloqué), résumé, mots-clés, longueur, note sans appel ou appel sans note, longue citation sans note, grec ou hébreu à contrôler, photo trop petite (floue à l’impression), titre seul en bas de page.","« ✓ Normes » sur chaque contribution : références bibliques (« Mt 25:31 » → « Mt 25, 31 »), documents du Magistère par leur sigle (« Lumen gentium 8 » → « LG 8 »), guillemets français ; vous cochez ce qui s’applique.","Impression : fonds perdus et traits de coupe pour un imprimeur ; devis calculé (pages, feuilles, agrafage ou dos collé, prix) ; conseil d’une épreuve à relire sur papier. Versions gardées : « ⇄ Comparer » montre en couleur ce qui a changé dans une contribution."]},{v:453,d:"2026-11-24",l:["Actes du symposium, un vrai livre de théologie : index des références bibliques (« Mt 25, 31-46 »), index des documents du Magistère (LG 8, CEC 1547…) et index des noms (auteurs cités, Pères de l’Église, papes), faits tout seuls avec les numéros de page ; page « Comment citer ce livre » (le livre et chaque contribution, avec ses pages).","Titres courants : l’auteur sur la page de gauche, le titre de la contribution sur la page de droite ; sommaire avec les numéros de page ; marge intérieure plus large (pliure et agrafes) ; le livret plié ajoute lui-même les pages blanches jusqu’à un multiple de 4, et prévient au-delà de 80 pages (dos collé).","La mémoire de l’événement en annexe : programme, discours d’ouverture et de clôture, homélie de la messe, synthèse des débats, photos avec légende ; glossaire des mots latins, grecs et hébreux (proposé à partir des mots en italique) ; paragraphes numérotés si on le souhaite."]},{v:452,d:"2026-11-24",l:["Actes du symposium : une feuille de style pour les intervenants, tirée de la Méthodologie du GSTF (longueur, notes, bibliographie, références bibliques, sigles du Magistère, résumé, date limite) : à imprimer, à copier dans un mail, ou à montrer aux professeurs dans leur portail.","Un calendrier de travail à rebours depuis la date du symposium (5 février 2027 d’après le calendrier académique) : remise des textes, relecture, corrections, bons à tirer, impression, distribution ; chaque date se modifie, et les échéances peuvent aller dans l’agenda.","Chaque contribution : un résumé, 3 à 5 mots-clés et un second résumé dans une autre langue (anglais, français, italien ou malgache). Une seule liste de sigles pour tout le livret : les sigles connus employés dans les textes (LG, CEC, DzH…) s’ajoutent tout seuls."]},{v:451,d:"2026-11-24",l:["Actes du symposium : le circuit complet de chaque contribution : reçue, en relecture, à corriger par l’auteur, corrigée, bon à tirer signé, publiée. Deux relecteurs (fond théologique et langue), avec la date de leur relecture ; « 📤 Pour le relecteur » imprime le texte, avec ou sans le nom de l’auteur (relecture à l’aveugle).","Autorisation de publication et bon à tirer : des fiches à imprimer et faire signer (le texte, les photos et les personnes qu’on y voit). Sans autorisation signée, le livret définitif est bloqué : seule une épreuve est possible.","Comité scientifique et coordination : nommés dans « Page de titre et mentions », imprimés au verso de la page de titre."]},{v:450,d:"2026-11-24",l:["Sans Internet : le site s’ouvre avec la dernière version reçue ; à chaque nouvelle version, l’appareil garde aussitôt le code de tout le site et les pages du Séminaire (plus seulement celles déjà ouvertes). Hors connexion, une ligne dit « Hors connexion – informations du … à … ».","Une demande (attestation, relevé, rendez-vous, message, intention…) écrite sans Internet est gardée sur l’appareil et part toute seule au retour de la connexion, avec un message ; de même pour un devoir en PDF (l’heure du dépôt est celle de l’envoi).","L’espace personnel de l’étudiant (ses notes, devoirs, présences, prêts) reste lisible sans Internet ; tout est effacé de l’appareil à la déconnexion. L’Administration s’ouvre sans Internet mais ne garde aucune donnée des étudiants : elle affiche « Ces données demandent Internet »."]},{v:449,d:"2026-11-24",l:["Bibliothèque : « 📮 Proposer l’achat à la bibliothèque » sous chaque livre trouvé sur internet (membres connectés). La bibliothécaire voit les propositions dans Gestion › « 📮 Demandes d’achat », les livres les plus demandés d’abord, avec le prix trouvé, et note la suite (acceptée, commandée, arrivée, refusée) ; chacun voit ses propositions et leur suite. Il faut le fichier SQL 176.","Administration et portails du personnel : ils se chargent en arrière-plan dès la connexion, pour être prêts quand on les ouvre. Pendant le chargement (connexion lente), une ligne « ⏳ Chargement de l’espace du personnel… » s’affiche ; en cas de coupure, le site réessaie tout seul deux fois, puis affiche « L’Administration n’a pas pu se charger » avec un bouton « ↻ Réessayer », au lieu d’une page vide."]},{v:448,d:"2026-11-24",l:["Bibliothèque : « Chercher dans : partout · l’auteur · le titre · le sujet » sous la case de recherche ; les autres façons d’écrire un auteur sont essayées toutes seules (Jaques → Jacques, Ratzinger ↔ Benoît XVI, John Paul II → Jean-Paul II, Thomas d’Aquin, de Lubac, von Balthasar…), puis le nom seul si le prénom est mal écrit ; sur internet, les éditions françaises et les articles en accès libre sont cherchés à part, et passent en tête.","« 🔔 Prévenez-moi » quand le Séminaire n’a pas encore le livre : la recherche est gardée sur cet appareil, et un nouveau livre du catalogue est signalé à la visite suivante de la Bibliothèque."]},{v:447,d:"2026-11-24",l:["Bibliothèque : quand le Séminaire n’a pas le livre cherché (« jacques dupuis »), les livres qui n’ont qu’un des mots (d’autres « Jacques ») sont repliés derrière un bouton, au lieu d’une longue liste sans rapport ; les articles trouvés sur internet s’ajoutent aux livres ; Google Livres est réessayé s’il ne répond pas, et le site dit quand aucun prix n’a été trouvé."]},{v:446,d:"2026-11-24",l:["À la demande du Père Préfet : quand le Séminaire n’a pas un livre ou un article, la recherche sur internet montre d’abord tout ce qui est gratuit (lecture libre, accès libre, prêt en ligne), puis ce qui est à vendre avec son prix exact (prix du livre numérique sur Google Livres, en euros, avec le lien d’achat). Pour un article payant, le site le dit et renvoie au site de l’éditeur, qui seul donne le prix ; les articles vendus à l’unité sur Cairn (Nouvelle Revue Théologique, Recherches de science religieuse…) sont signalés, et la NRT a son lien de recherche."]},{v:445,d:"2026-11-24",l:["Bibliothèque › « En ligne, gratuit » : quand rien n’est trouvé en ligne, le site cherche aussitôt dans le catalogue du Séminaire et montre les livres trouvés, avec un bouton « Voir dans tout le catalogue » ; puis les articles et les livres trouvés sur internet (OpenAlex, Google Livres…), ceux qu’on peut lire gratuitement d’abord, avec des liens vers Persée, Cairn, HAL, Google Scholar, Open Library, Internet Archive. Une faute dans un mot (« Jaques Dupuis ») n’empêche plus de trouver : le site garde l’autre mot (« Dupuis ») et le dit."]},{v:444,d:"2026-11-24",l:["« Aide » calcule sur l’emploi du temps, les cours, le calendrier et la liturgie du site : un professeur a-t-il cours tel jour ? quel est le 2e cours des 3e année le 4 juin ? combien de séances de Patrologie ont eu lieu au 5 décembre, combien restent ? premier et dernier cours d’une matière, jours d’enseignement d’un professeur dans un mois, ses séances par semestre, les cours d’une classe une semaine donnée, la fête et la couleur liturgique d’une date (« liturgie du 12/11 »), la durée des vacances et des examens, les chiffres du livret (part d’un diocèse, religieux par année), et pour l’administration les anomalies de l’emploi du temps. Elle vérifie aussi une note de bas de page selon la Méthodologie (« Ma note est-elle juste : … ») et cherche un livre du catalogue par son titre (« Qui est l’auteur de « … » ? »)."]},{v:443,d:"2026-11-24",l:["« Aide » répond pour la personne connectée, avec ses propres informations (elle seule les voit) : « Mon prochain cours », « Mon livre est à rendre quand ? », « Mes notes sont-elles publiées ? » ou « Pourquoi je ne vois pas mes notes ? » (date de publication, notes pas encore saisies…), « Où en est ma demande d’attestation ? », « Mon prochain rendez-vous avec le Préfet ».","Elle suit la conversation (« Qui enseigne l’Eucharistie ? », puis « et la Catéchèse ? », puis « en quelle année ? »), demande quand elle hésite (« un papier » : relevé, attestation, carte ou bulletin ?), comprend une question en anglais ou en italien (réponse en français, en le disant), et cherche un livre par son titre (« Avez-vous Jésus de Nazareth ? », avec sa disponibilité). Sans Internet, si elle n’a jamais pu se charger, elle montre l’essentiel : téléphone, adresse, horaires, et qui aller trouver si ça ne va pas."]},{v:442,d:"2026-11-24",l:["« Aide » répond par le fait lui-même : « Combien de jours avant les examens ? », « Quel dimanche sommes-nous ? », « Combien de cours en 3e année ? », « Combien d’heures au 2e semestre ? », « Quels cours donne le P. … ? » (et, si deux professeurs ont le même nom, elle montre les deux), « Le cours de Latin est quel jour ? », « Combien d’absences sont permises ? » (avec l’article du règlement), « À qui m’adresser pour payer ? ». Elle comprend « ecclésio 2 », « DC », « 3e A », « L1 », « S2 ».","Elle dit clairement ce qu’elle ne fait pas : rédiger un devoir, donner les réponses d’un examen, montrer les notes d’un autre, répondre à une question de théologie à la place du professeur. Une demande de code ou d’argent reçoit l’avertissement « arnaque ». Un visiteur reçoit le nombre d’étudiants (chiffre public), jamais de noms ; un enseignant non indiqué est « à confirmer »."]},{v:441,d:"2026-11-23",l:["À la demande du Père Préfet, pour simplifier : en haut du Tableau de bord, un bouton « 📝 Saisir ou importer des notes » ouvre directement Portail Professeur › « Appel et notes ». Dans « Notes à saisir », chaque cours a son bouton « 📝 Saisir » : le professeur et la matière sont déjà choisis, la liste de la classe est là ; il reste à taper les notes ou à cliquer « 📥 Importer les notes » (photo, PDF, Word, Excel)."]},{v:440,d:"2026-11-23",l:["Administration › Étudiants et Enseignants : la colonne des boutons (Enregistrer, Nouveau mot de passe, Modifier, Retirer, Supprimer) reste toujours visible à droite, même sur un écran étroit : les autres colonnes glissent dessous."]},{v:439,d:"2026-11-23",l:["Administration › Étudiants et Enseignants : « Modifier nom / origine » ouvre une fenêtre du site (nom, prénoms, diocèse ou congrégation à choisir dans la liste) au lieu des petites fenêtres du navigateur, que Edge ou Chrome peuvent bloquer sans rien dire. « Retirer » et « Supprimer définitivement » montrent tout de suite « ⏳ Vérification… » pendant que le site vérifie la base ; avec une connexion lente, la fenêtre « Retirer » s’ouvre au plus tard après 5 secondes."]},{v:438,d:"2026-11-23",l:["À la demande du Père Préfet : la fiche de présence d’une classe de 102 séminaristes tient sur 2 pages (lignes un peu plus serrées au-delà de 25 noms) ; à la fin, la date à gauche et la signature à droite, sur la même ligne. « 🖨 Listes de classe » : on choisit le semestre (S1 ou S2), puis la matière dans la liste des cours de la classe ; son professeur se met tout seul (on peut le changer). « Laisser en blanc » garde la ligne à écrire à la main ; « Autre… » permet encore d’écrire. Plus de frappe, plus d’oubli ni de faute."]},{v:437,d:"2026-11-23",l:["« Aide », d’après les essais du Père Préfet : « je veux aller à l’Apparence », « ouvre les homélies »… ouvre directement la rubrique de l’Administration ; « combien d’étudiants en L1 ? » donne le nombre de séminaristes (par année, ou le total), avec un bouton vers la liste (seulement pour le Père Préfet, le Père Recteur et le secrétariat) ; « samedi prochain, à quelle heure le cours d’histoire ? » ne montre que les cours d’histoire de ce jour-là ; « je veux aller à la bibliothèque » ouvre la page ; « qui est le professeur d’Ecclésiologie II ? » ne montre que ce cours (et non I, II et III) ; « où est l’onglet Vie de l’Église ? » explique que c’est un cadre de la page d’accueil et le montre ; les étapes ne sont plus numérotées deux fois (« 2. 1. ») ; nouvelle fiche « Changer le logo du site et de l’application » ; « je veux insérer la liste des étudiants en L1 avec leurs notes » explique que la liste est déjà dans le site et comment taper ou importer les notes (photo, PDF, Word, Excel)."]},{v:436,d:"2026-11-23",l:["À la demande du Père Préfet : l’onglet « Administration » est visible par tous. Un visiteur voit la liste des rubriques (Tableau de bord, Actualités, Annonces, Articles, Homélies…) et une ligne qui dit à quoi chacune sert ; il ne peut rien ouvrir : chaque rubrique affiche « réservée au Père Préfet, au Père Recteur et au secrétariat » et le bouton « Se connecter ». Les données restent protégées par la base."]},{v:435,d:"2026-11-23",l:["« Aide » et la recherche du site (🔍) trouvent mieux une personne : pour le Père Préfet, le Père Recteur et le secrétariat, la recherche porte aussi sur toute la liste des étudiants, y compris ceux qui ont quitté le Séminaire (avec la mention). « cherche … » sans résultat répond clairement « je ne trouve personne de ce nom » au lieu de proposer des livres ; le nom cherché n’est jamais enregistré.","Correction : la recherche du site (🔍) pouvait s’arrêter sur un nom propre quand « Aide » n’avait pas encore été ouverte."]},{v:434,d:"2026-11-23",l:["Un lien qui demande quelque chose (confirmation d’abonnement, retour de Google Drive, vérification…) s’ouvre toujours tel quel, même pour une personne connectée.","En anglais et en italien, une ligne discrète en haut dit « traduction provisoire, en cours de relecture ; la version française fait foi »."]},{v:433,d:"2026-11-23",l:["Anglais et italien : tout le texte fixe des pages publiques est traduit (accueil, études, bibliothèque, agenda, contact, prières, confidentialité, archives, entretiens…), ainsi que les dates, les jours et les dimanches du temps liturgique. Les textes écrits par le Séminaire (articles, homélies, méditations, contenu des syllabus) et les textes officiels de la liturgie restent en français."]},{v:432,d:"2026-11-23",l:["Un accueil pour chacun : à l’ouverture du site, une personne connectée arrive directement dans son espace : l’étudiant dans son Portail (« Ma semaine »), le professeur et l’éducateur dans le leur, le Père Préfet, le Père Recteur et le secrétariat sur le Tableau de bord. L’accueil public reste à un clic ; « Toujours ouvrir l’accueil » garde l’ancien comportement sur cet appareil. Un lien précis (#…) ouvre toujours la page demandée."]},{v:431,d:"2026-11-23",l:["Le titre de l’onglet du navigateur suit la partie ouverte (« Études – Syllabus des cours – GSTF Faliarivo », « Bibliothèque – GSTF Faliarivo »…) : plus clair dans les favoris, l’historique et Google.","Lecteurs d’écran : les vidéos ont une description, et chaque bouton qui ne montre qu’un symbole (🖨, ✏️, 🗑, ▶…) a un nom lisible.","Trois pages de plus pour Google : programme des études (cours, heures, professeurs), corps enseignant, calendrier académique ; le plan du site donné à Google en compte maintenant 10."]},{v:430,d:"2026-11-23",l:["Accueil plus rapide en connexion lente : la grande photo existe en trois tailles (le téléphone reçoit la petite, 21 Ko au lieu de 136 Ko) et elle est chargée en priorité ; le logo est 20 fois plus léger. Mesure en 3G lente simulée (0,4 Mbit/s, 2 s d’aller-retour) : la photo de l’accueil apparaît en 4,5 s au lieu de 10,8 s ; le premier texte reste à 2,8 s ; la première visite charge 530 Ko au lieu de 686 Ko.","Le moteur de compréhension de « Aide » (v425, v427) n’est plus chargé avec l’accueil : seulement quand on ouvre « Aide »."]},{v:429,d:"2026-11-23",l:["« Aide », après le test en ligne de notre ami : « Quand commence le 2e semestre ? » donne la date du début des cours, sans le titre du semestre qui disait autre chose ; « qui est l’administrateur principal du site ? » mène à « Qui gère le site ? » (sans nom) ; « ma carte d’étudiant », « où je remets mon mémoire », « quels livres j’ai empruntés » mènent à la page personnelle (pour un visiteur : se connecter) ; « SMS bizarre » mène tout de suite à « message suspect » ; le correcteur ne change plus « premier »."]},{v:428,d:"2026-11-23",l:["État du site › « 💓 Réveils de la base » : le réveil interne s’appelle « témoin interne » (il ne réveille pas la base, il prouve qu’elle tournait) ; la note explique que ce sont les réveils GitHub et cron-job.org qui empêchent la pause, et que l’alerte, si la base dort, vient de cron-job.org par email."]},{v:427,d:"2026-11-22",l:["« Aide » répond avec la vraie information du site : « Qui est le recteur ? », « Qui est Razafiniarivo Rodolphe ? » (équipe formatrice, foyers, professeurs et leurs cours ; jamais les étudiants), « Quand commencent les vacances de Noël ? », « Quand sont les examens du premier semestre ? » (calendrier académique), « Y a-t-il un cours de christologie ce soir ? », « Quels cours demain en 2e année ? », « Quels sont les cours de la 3e année ? » (emploi du temps et liste des cours).","« Aide » ne tient plus compte des formules de politesse en tête de question (« Dites-moi… », « Pouvez-vous me dire… », « J’aimerais savoir… ») ; « Quels sont les problèmes les plus fréquents ? » reçoit la liste des fiches de dépannage (pour l’administration, avec les vrais chiffres des 30 derniers jours).","Nouvelles fiches : « Qui gère le site ? », « Historique de la liste des étudiants » ; fiches complétées : « Saisir les notes et les présences », « Supabase en pause »."]},{v:426,d:"2026-11-22",l:["Calendrier des examens (avec le SQL 175) : Administration › Année académique › « 📝 Calendrier des examens » : pour chaque classe, le cours, la date, l’heure, écrit ou oral, la salle ; modifier, retirer, imprimer le calendrier d’une classe.","Portail Étudiant › « Ma semaine » : les examens de sa classe apparaissent dès 15 jours avant ; « Tout le calendrier des examens de ma classe » se déplie."]},{v:425,d:"2026-11-22",l:["« Aide » comprend mieux les expressions du métier, grâce au travail de notre ami (sans intelligence artificielle) : « les bulletins de la 2e année » mène aux relevés de notes, « enlever un séminariste qui a quitté » à Administration › Étudiants, « les anciens examens » aux annales, « le programme de la 3e année » aux syllabus, « l’attestation à préparer » à Lettres et attestations, « mettre la méditation » à Méditations.","« Je ne veux plus que mon numéro apparaisse » mène à « Choisir ce que les autres voient de mes coordonnées ». La détresse reste vérifiée en premier, comme avant."]},{v:424,d:"2026-11-22",l:["Listes d’examen (Portail Professeur) : chaque liste imprimée est gardée par le site telle quelle, avec son numéro (LE-…) en bas de la feuille ; personne ne peut la modifier ni l’effacer (avec le SQL 174).","« 📂 Listes d’examen gardées » sous la liste des étudiants : revoir une ancienne liste exactement comme elle était, et joindre, si on le souhaite, la photo de la feuille signée (une seule fois)."]},{v:423,d:"2026-11-22",l:["Relevés de notes : « Montrer aussi les étudiants partis ». Un séminariste retiré (« parti ») qui a des notes reparaît dans la liste avec la mention « parti », et son relevé s’imprime comme celui des autres. Les années déjà figées restent dans l’onglet « Archives »."]},{v:422,d:"2026-11-22",l:["Relevés de notes : en haut, « 🔒 Figer les bulletins de l’année » (Père Préfet ou secrétariat). Le site montre, par classe, combien de bulletins seront figés et les notes qui manquent encore, puis demande « Je confirme ». Ensuite : « ✓ Bulletins figés le … par … ».","Avec le SQL 173 : plus aucun archivage automatique le 1er juillet (décision du Père Préfet : tout est à sa place fin juillet). À partir de juin, le Tableau de bord rappelle les bulletins pas encore figés."]},{v:421,d:"2026-11-22",l:["Listes de classe (Administration › Étudiants › « 🖨 Listes de classe ») : la fiche de présence et la liste de classe d’une classe ou des trois, d’après la base à l’instant ; seuls les séminaristes présents, numérotés de 1 à N dans l’ordre alphabétique, sans ligne vide ; la date et l’heure de la liste en bas.","Portail Professeur : les mêmes numéros que sur la fiche ; « Marquer absents » : écrivez les numéros des absents (ex. 3, 12, 45), le site les coche, vous vérifiez puis enregistrez. La recherche accepte aussi un numéro."]},{v:420,d:"2026-11-22",l:["État du site : « 💓 Réveils de la base » montre la date du dernier réveil réussi de chacune des trois sources (interne, GitHub, surveillance externe), et prévient si l’une s’arrête (« réveil GitHub arrêté »…). Avec le SQL 172."]},{v:419,d:"2026-11-22",l:["Les rôles du personnel (avec le SQL 171) : seul le Père Préfet des études attribue ou retire un rôle (« 🔑 Rôles », avec son deuxième code) ; la secrétaire inscrit un nouveau professeur comme « Enseignant » et peut proposer un changement, que le Père Préfet accepte ou refuse.","Le Recteur voit tout, comme le Père Préfet, en lecture seule dans l’administration (ses propres cours restent ouverts) ; pour l’évaluation des cours, il voit les résultats sans les noms. Un seul Préfet et un seul Recteur ; le Préfet nomme lui-même son successeur.","« 🔑 Mes rôles » : sur son portail et sur le Tableau de bord, chacun voit ses rôles et ce qu’ils lui permettent (la secrétaire, tout ce qui relève d’elle et ce qui revient au Père Préfet seul).","Plusieurs rôles par personne (un professeur peut être aussi éducateur : il a alors les deux portails), avec des dates de mandat : à la date de fin, le rôle se retire tout seul. Nouveaux rôles : Vice-recteur (comme les éducateurs) et Maître des cérémonies (la fiche du groupe Liturgie). Chaque changement est noté dans le journal des rôles."]},{v:418,d:"2026-11-22",l:["Chercher une personne : dans « Aide » ou la loupe 🔍, écrivez « cherche Roméo, L3 » ou simplement un nom. Le site montre les personnes, avec « 📒 Dans l’annuaire » (et « 📊 Bulletin » pour l’administration). « L3 », « 3e année »… limitent à une classe. Seulement pour les membres connectés, avec les mêmes droits que l’Annuaire ; rien n’est enregistré."]},{v:417,d:"2026-11-22",l:["Livret académique : « 🎨 Couverture du livret » est maintenant en haut de la page, avant « 📘 Fabriquer le livret », qui la rappelle (« ↑ Voir la couverture »)."]},{v:416,d:"2026-11-22",l:["Aide : elle connaît tout le plan du site, lu dans les vrais menus (onglets, Espace du Séminaire, Études, Administration, groupes, pages) et les rubriques des portails. « Où se trouve… ? », « où sont… ? », « où trouver… ? » reçoivent d’abord le chemin (ex. « Études › Outils de l’étudiant › Annales d’examens »), avec « Y aller », puis le mode d’emploi.","Aide : une page réservée est dite réservée (« 🔒 réservé à l’administration : Administration › Étudiants › Cartes d’étudiant ») au lieu d’une autre réponse ; « carte » avec « étudiant » est la carte d’étudiant, jamais la carte de Madagascar ; « tous les étudiants » n’emmène plus à l’annuaire quand on parle d’autre chose.","Évaluation des cours (Administration) : le mode d’emploi ne dit plus « anonyme » : les réponses sont confidentielles, le Père Préfet voit les noms, les professeurs jamais."]},{v:415,d:"2026-11-22",l:["Aide : « Où se trouvent les cartes de tous les étudiants ? » reçoit maintenant sa réponse (Administration › Cartes d’étudiant)."]},{v:414,d:"2026-11-22",l:["Relevé de notes de 3e année : le cadre de l’examen de fin de cycle (ORAUX et ÉCRIT) est de nouveau imprimé comme avant, avec ses lignes vides à remplir à la main tant que les épreuves ne sont pas saisies. La mise sur une seule page reste.","Relevé de notes : la signature et le cachet restent exactement à la place choisie dans « 🎨 Couleur, place et cachet » (le nom du signataire ne descend plus).","Relevé de notes : le pied de page (adresse du Séminaire) est fixé en bas de la première page : il ne part plus seul sur une deuxième page (1re, 2e et 3e année).","Administration › Ma signature : l’aperçu ne déborde plus sur le texte du dessous ; le cadre s’agrandit pour montrer la signature et le cachet à leur place, sans les déplacer.","Relevé de notes : le code QR est plus grand (23 mm au lieu de 15 mm), plus facile à lire avec un téléphone."]},{v:413,d:"2026-11-22",l:["Bibliothèque, plus simple : une seule grande recherche et trois voies (📚 Tout le catalogue · 🌐 En ligne, gratuit · 🎓 Mémoire et thèse) ; les disciplines et les infos pratiques sont repliées ; « Mes emprunts » n’apparaît que s’il y a quelque chose.","Bibliothèque, plus savante (🎓 Mémoire et thèse) : recherche avancée (titre, auteur, années, discipline, langue, niveau A), « ➕ Ma liste » sous chaque livre et chaque ressource, puis une bibliographie à copier ou un fichier pour Zotero (RIS) et LaTeX (BibTeX) ; le filtre « niveau A » est réservé aux membres connectés.","Ma liste de travail reste dans l’appareil : un avertissement le rappelle ; « 💾 Sauvegarder ma liste » la garde dans un fichier, « 📂 Recharger » la retrouve sur un autre appareil."]},{v:412,d:"2026-11-22",l:["Relevé de notes de 3e année : une ligne d’examen sans intitulé ni note n’est plus imprimée (plus de tableau « ÉCRIT » vide) ; TOTAL et Moyenne seulement quand il y a des notes.","Relevé de notes : la signature ne barre plus le nom du signataire (le nom descend juste en dessous), et un relevé un peu trop long est resserré pour tenir sur une seule page, pied de page compris."]},{v:410,d:"2026-11-22",l:["« Aide », réponse de détresse : la consigne immédiate « ne restez pas seul : allez tout de suite réveiller un formateur ou un confrère, même la nuit, ou appelez les secours » (en français, anglais et italien).","Sécurité : règles CSP dans la page (le code ne peut venir que du site et des bibliothèques connues) ; avec le SQL 170, les visiteurs ne lisent plus les colonnes internes des ressources (décision, motif, fiabilité, texte reproduit)."]},{v:409,d:"2026-11-21",l:["Contact et plan d’accès : lien vers la fiche Google Maps officielle du Séminaire (photos, avis, téléphone, itinéraire)."]},{v:408,d:"2026-11-21",l:["« Aide » sur téléphone : la fenêtre prend presque tout l’écran, pour lire les réponses plus facilement ; « ♡ Besoin d’aide ? » devient une petite ligne en bas de la fenêtre."]},{v:407,d:"2026-11-21",l:["Vitesse : la liste des nouveautés et la gestion de la bibliothèque ne sont plus téléchargées par les visiteurs (elles se chargent quand on les ouvre) ; le mode « connexion faible » se met aussi tout seul en 3G (on peut le retirer : Affichage › 📶).","Administration, État du site (avec le SQL 169) : « 🛡 Sécurité et sauvegarde » : qui a activé le deuxième code avant le 1er décembre, dernière restauration testée, avertissements du Security Advisor, dernier « Test réel ».","Examen de « Aide » refait sur la version 406."]},{v:406,d:"2026-11-21",l:["Bibliothèque de recherche (avec le SQL 168) : chaque ressource a sa « 📋 Fiche » : contenu, couverture, utile pour, limites, texte reproduit (quelle édition, quelle traduction), éditeur, identifiant, note de fiabilité A/B/C, copie de secours de l’Internet Archive.","Les ressources sont annoncées en trois chiffres (outils de recherche · documents du Magistère · textes et sources), avec un filtre par nature et « Niveau A seulement (pour une thèse) ».","Les 46 thèmes écrits à la main deviennent 18 disciplines (liste fermée, la même que les thèmes) ; fiches des 40 outils de recherche ; corrections demandées par notre ami ; 8 nouvelles ressources à valider ; liens essayés chaque lundi."]},{v:405,d:"2026-11-21",l:["Ressources en ligne, validation plus sûre : « ✓ Valider » s’active seulement après trois vérifications cochées (le lien, le résumé, la gratuité) ; « ⏸ Mettre de côté » pour un professeur et « ✗ Refuser » avec un motif ; « ↶ Annuler » pendant 8 secondes ; compteur « traitées / total ».","Avec le SQL 167 : le serveur note qui a décidé et quand (journal), refuse un doublon, et affiche l’origine de chaque résumé ; les 7 ressources que le développeur n’avait pas ouvertes reviennent à valider.","« Retirer du public » une ressource déjà publiée, avec le motif. Pour les lecteurs : « ✓ Fiche vérifiée par la bibliothèque le … »."]},{v:404,d:"2026-11-21",l:["Bibliothèque, gestion des ressources en ligne plus simple : le ou la bibliothécaire ne voit que les nouvelles ressources à valider, rangées par rayon, chacune avec sa référence complète et son résumé ; « ✓ Valider » la fait entrer dans la bibliothèque et disparaître de la page ; « ✗ Ne pas publier » la laisse cachée.","Avec le SQL 166 : un résumé pour chaque ressource (70 résumés écrits pour les ressources à valider), visible aussi par les lecteurs.","« Tous les livres de A à Z » montre aussi les ressources en ligne, marquées 🌐 (sans les compter parmi les livres) ; « ❝ Citer » donne la référence d’une ressource ; un thème sans ressource le dit clairement."]},{v:403,d:"2026-11-21",l:["Bibliothèque : tapez une référence (« Jn 3,16 », « CIC 1024 », « LG 8 », « ST I q.2 a.3 », « CEC 1234 », « DH 3008 ») : le texte officiel s’ouvre directement, et la recherche normale continue en dessous.","Ressources en ligne rangées en 7 rayons, selon les sources de la théologie : Écriture, Tradition, Magistère, théologiens, philosophie, histoire et Église en Afrique, revues et outils.","Avec le SQL 165 : 14 nouvelles ressources pour la recherche (STEP Bible, IxTheo, Logeion, saint Thomas, saint Augustin, Acta Apostolicae Sedis, PhilPapers…)."]},{v:402,d:"2026-11-21",l:["« Aide » et la détresse, troisième étape (après la deuxième série secrète de notre ami : 29 sur 32) : « ne plus me réveiller » sous toutes ses formes, « la vie n’a plus de sens » avec « partir », des médicaments « prêts », et « je vais mal » partout dans la phrase (au moins la ligne douce). Une phrase qui parle de la vie, du réveil ou dit « je vais mal » n’est plus gardée (SQL 164)."]},{v:401,d:"2026-11-21",l:["« État du site » vérifie aussi les SQL 159 à 163 (détresse, sécurité, limites, portes publiques). Pour le 162, la page voit seulement que la fonction de détresse existe : la photo du résultat reste la preuve qu’il a été lancé."]},{v:400,d:"2026-11-21",l:["Page « Prières » : en tête, la « Liturgie du jour » : le temps et la semaine en grand, la couleur, la date ; la fête du jour et les lectures ; neuf tuiles (psautier, rosaire, lectures, saint du jour, office de maintenant, prières du Séminaire, homélies, demain, intention) ; la dernière méditation avec son vrai titre. Tout est calculé sur l’appareil, même sans connexion.","Confidentialité : la page dit maintenant comment l’adresse internet sert, brouillée, à arrêter les robots."]},{v:399,d:"2026-11-21",l:["Accueil : « Méditation du jour » seulement si elle est datée d’aujourd’hui ; sinon « Dernière méditation · vendredi 20 novembre » (ou « Méditation de demain » le soir, après 23 h).","Cadre « Liturgie du jour » : les mots dans la langue du site, même si les lectures viennent d’une source italienne (signalée « it. ») ; une ligne de repères calculée sans Internet : semaine, psautier, mystères du rosaire, cycle des lectures (ex. « 33ᵉ semaine du T.O. · Psautier I · Mystères joyeux · Année A, paire »)."]},{v:398,d:"2026-11-21",l:["Sécurité (avec le SQL 163) : renouveler un emprunt sans compte demande le nom de famille complet (et non quelques lettres), avec un nombre d’essais limité.","Demander un livre et poser une question sur un article : limités par appareil, contre les robots.","Mesures de vitesse du site limitées ; la liste des fichiers des dossiers publics n’est plus donnée à tout membre connecté (les photos et documents s’ouvrent toujours par leur lien).","Les tables techniques de la sécurité ne sont plus copiées dans les sauvegardes."]},{v:397,d:"2026-11-21",l:["« Aide » et la détresse, deuxième étape (après l’examen secret de notre ami) : la détresse se lit sur la phrase telle qu’elle a été écrite, avant toute correction d’orthographe (« pendre » n’était plus vu).","Reconnus en plus, en français, en anglais et en italien : les moyens (se pendre, médicaments, pilules, sauter…), les formes conjuguées (« la faccio finita », « end it tonight ») et les façons voilées (« partir pour toujours », « à quoi bon vivre »…) ; la solitude et le désespoir reçoivent une main tendue.","« Mourir de rire » n’est plus pris pour une détresse.","Une phrase qui contient un mot de mort ou un moyen n’est jamais gardée, même si elle n’est pas reconnue (le site et la base, SQL 162)."]},{v:396,d:"2026-11-21",l:["Sécurité (avec les SQL 160 et 161) : les fonctions de la base sont fermées par défaut ; seules celles dont le site a besoin restent ouvertes, comme avant. Les compteurs (visites, lectures, « Aide ») sont limités par adresse : un robot ne peut plus fausser les chiffres ni remplir la base.","Connexion par le nom : un inconnu qui tape le nom d’un séminariste ne bloque plus que lui-même.","Deuxième code obligatoire pour l’administration à partir du 1ᵉʳ décembre 2026 ; jusque-là, un rappel par jour.","PDF réservés (articles, annales, documents de cours) : le lien est créé au moment où l’on touche « Ouvrir » ou « Télécharger », et ne vaut que 2 minutes."]},{v:395,d:"2026-11-21",l:["« Aide » et la détresse : beaucoup plus de façons de dire qu’on va mal sont reconnues, en français, en anglais et en italien (« je ne veux plus vivre », « mettre fin à mes jours », « I wish I were dead », « end it all », « vorrei essere morto »…) ; la réponse vient dans la langue de la phrase. Le malgache reste tel quel en attendant la relecture du Père Préfet.","Trois niveaux : détresse (réponse complète, avec les secours), souffrance (une personne d’abord), fatigue ou tristesse (la réponse habituelle, plus une ligne pour parler à un prêtre et le bouton « 🤍 Je ne vais pas bien »). Aucun de ces messages n’est envoyé ni gardé.","« Je veux disparaître de l’annuaire » n’est plus pris pour une détresse.","Avec le SQL 159 : la base elle-même refuse de garder ces phrases, masque les téléphones (6 chiffres ou plus) et les adresses email des questions gardées, et efface après 6 mois la liste des questions sans réponse."]},{v:394,d:"2026-11-21",l:["Bibliothèque, ressources en ligne : toute la carte s’ouvre au toucher, et la pastille devient un vrai bouton « 🌐 Ouvrir · gratuit ↗ ». Une seule liste, sans doublon (ex. le Code de droit canonique n’apparaît plus deux fois).","Étiquettes QR : une étiquette par exemplaire (« ex. 1/3 »…), aucune pour une fiche à revoir, une planche d’essai d’abord ; si les livres n’ont pas encore de cote, l’écran le dit.","Prêter avec le téléphone : il est écrit que le scan se fait avec l’appareil photo du téléphone du ou de la bibliothécaire.","Recherche d’un livre que la bibliothèque n’a pas : les livres trouvés sur internet (Google Livres, Open Library, OpenAlex) s’affichent maintenant tout seuls, en premier, même quand la bibliothèque a des « résultats approchants » (avant : seulement quand il n’y avait aucun résultat, ce qui n’arrivait presque jamais)."]},{v:393,d:"2026-11-21",l:["Sécurité (avec le SQL 158) : les photos, miniatures et PDF d’une actualité réservée aux membres ne sont plus dans l’espace public. Ils sont dans un espace privé et ne s’ouvrent que par un lien temporaire (1 heure), donné à une personne connectée qui peut voir l’actualité. L’ancienne adresse ne s’ouvre plus. Les anciennes actualités réservées sont mises à l’abri toutes seules à l’ouverture d’Administration › Actualités ; une actualité qui redevient publique retrouve l’espace public."]},{v:392,d:"2026-11-20",l:["« Aide » connaît mieux le site : 12 fiches corrigées (boutons renommés : « 📖 Fiche du livre », « 🔔 Recevoir les notifications », recherche de la bibliothèque par groupes…) et 4 nouvelles (les prières du Séminaire, modifier les prières, les retards à rappeler, les liens morts).","Le téléphone, l’email, les horaires du secrétariat et les règles du prêt ne sont plus écrits dans les fiches : ils sont lus dans les réglages (Contact, Bibliothèque). Si le réglage change, la fiche change avec lui.","Chaque fiche porte une date, mise toute seule à chaque changement ; un examen automatique vérifie à chaque version que chaque bouton cité existe et que chaque lien « Aller » mène quelque part."]},{v:391,d:"2026-11-20",l:["Méditations et homélies datées d’un jour futur (avec la fonction v69) : elles paraissent la veille à 23 h (heure de Madagascar), pour être lues dès le soir ; la notification et les emails partent le jour même à 6 h, pour ne réveiller personne. Les autres articles programmés ne changent pas (0 h 01)."]},{v:390,d:"2026-11-20",l:["Cadre « Bonjour » personnalisé (avec le SQL 157) : vos choix (cartes, ordre, noms, « Ma note ») vous suivent sur tous vos appareils où vous êtes connecté. Personne d’autre ne les voit. À la déconnexion, rien ne reste sur un ordinateur partagé."]},{v:389,d:"2026-11-20",l:["Accueil, cadre « Bonjour » : chacun peut le personnaliser pour lui-même (« ✏️ Personnaliser ») : cartes affichées ou masquées, ordre, noms, et une carte « 📝 Ma note ». Gardé sur l’appareil.","Les cartes vides (pas de cours, pas d’annonce, aucun livre à rendre) tiennent sur une seule ligne ; le soir, la liturgie de demain vient en premier, avec sa date.","Mode « Contraste fort » : les petits titres du cadre restent clairs sur le fond sombre (avant : gris foncé sur bordeaux, presque illisibles).","Le bouton « 🙏 Prières » du bas, en double avec « Prière du temps présent », est retiré ; en haut à droite, « Mon espace › » remplace « Mon compte : dans mon portail »."]},{v:388,d:"2026-11-20",l:["Bibliothèque (avec le SQL 156) : une recherche qui a la forme d’une cote (ex. « 200 RAH ») ne cherche plus que dans les cotes (avant : « Robert SaRAH ») ; sans résultat, le site dit « aucun livre n’a cette cote ».","Les fiches « Livres acquis en… » (des listes, pas des livres) n’ont plus de bouton « Emprunter » : « Fiche en cours de vérification par la bibliothèque », en attendant que le ou la bibliothécaire les supprime."]},{v:387,d:"2026-11-20",l:["Allègement : les modèles d’invitation du Sakafom-pitiavana (et leur photo) ne se chargent plus que pour l’administration. Le fichier principal du site redevient presque aussi léger qu’en v380 (413 Ko compressés au lieu de 502 Ko en v386). Sans autre changement."]},{v:386,d:"2026-11-20",l:["Bibliothèque (avec le SQL 154) : recherche plus juste : d’abord les livres qui contiennent TOUS les mots, puis « résultats approchants » ; une cote cherche d’abord la cote exacte ; un nom de thème (« mariologie ») montre le thème ; faute de frappe : « Vouliez-vous dire… ? » (ou correction automatique s’il n’y a aucun résultat) ; résumés venus d’internet coupés après quelques lignes avec « Lire la suite ».","Bibliothèque : « Voir tous les livres » en liste courte avec l’index A B C… Z ; « ❓ Comment emprunter un livre ? » ; une seule liste des ressources en ligne avec des filtres (type, langue) ; « site non sécurisé (http) » signalé.","Livre à rendre ou en retard : rappel en haut de « Mon espace » ; pour le ou la bibliothécaire : « 📞 Retards à rappeler de vive voix » avec les téléphones.","Gestion de la bibliothèque : « 🧭 Thèmes à valider » (1 principal, au plus 1 secondaire ; ensuite le thème vient du sujet validé), « fiches à revoir », doublons mieux repérés (même éditeur et même année), auteurs écrits autrement (majuscules, « II »), « Passer en https ».","Avec la fonction v67 et le SQL 155 : les liens des ressources en ligne sont essayés chaque mois ; un lien mort crée une alerte.","Accueil et pages publiques : carte des diocèses sans « 0 » (point gris = moins de 3) et légende des barres grises ; « Homélie du dimanche » sur toute la largeur ; couvertures d’articles sans image en simple bandeau (homélies d’une autre couleur que les méditations) ; boutons Facebook et WhatsApp plus lisibles ; liens du bas de page et boutons FR/EN/IT plus grands ; textes de la barre du bas à 12 px ; citations des piliers cachées sur téléphone (accueil plus court)."]},{v:385,d:"2026-11-20",l:["Sakafom-pitiavana : « Thème de l’édition » dans les réglages : billet, enveloppe, image WhatsApp et invitation prennent le même style (Roses ivoire, Perles et ruban, Or sobre, Verdure, Photo du Séminaire).","Invitations : nouveau modèle « Photo du Séminaire » ; les anciennes cartes rangées parmi les modèles ; options marge imprimante (5 mm), économie d’encre (fond blanc) et code QR « plan d’accès » ; « malagasy d’abord » (vos textes malagasy passent devant) ; date sur une seule ligne ; ligne des réservations plus grande.","Le jour de la fête : affiches A4 et A3, numéros de table, marque-places (rien n’est enregistré), carte du menu, carte de remerciement.","Page d’impression rangée en trois groupes (Billets, Enveloppes, Invitations). Les polices des documents sont gardées dans le site (fichier polices-sk.css) : l’impression reste belle même avec une connexion faible.","Les étiquettes « Nouveau » disparaissent après 15 jours."]},{v:384,d:"2026-11-20",l:["Sakafom-pitiavana : « 🎨 Modèles d’invitation ». Six cartes A5 sans logo, à choisir au moment voulu : quatre modèles conçus (Roses ivoire, Perles et ruban, Or sobre, Verdure et roses), remplis tout seuls avec les réglages (date, heure, salle, participation, textes français et malagasy), et deux fonds à concevoir (titre et texte libres). Impression en A5, ou deux cartes sur une feuille A4 ; « Enregistrer au format PDF » donne un fichier."]},{v:383,d:"2026-11-20",l:["Inscription (avec la fonction v66) : quand une demande est acceptée, l’étudiant reçoit dans un seul email ses accès, sa fiche d’accès et sa fiche d’étudiant (deux PDF joints), et les liens vers la méthodologie du GSTF et le guide d’utilisation du site (dernières versions publiées dans Études › Documents officiels ; titre contenant « Méthodologie » ou « Guide »). S’il manque un document, l’administration est prévenue. Un simple changement de mot de passe n’envoie que les accès, comme avant."]},{v:382,d:"2026-11-20",l:["Demandes d’inscription : une même personne qui envoie deux demandes (même nom et prénoms, ou même email, ou même téléphone) est signalée « ⚠️ Même personne ». Si l’une est déjà acceptée, le bouton « Accepter » disparaît de l’autre (il créerait un deuxième compte) ; un bouton « Classer comme doublon » la range parmi les refusées, sans rien envoyer au candidat. Avant d’accepter, le site vérifie aussi qu’aucun étudiant du même nom n’est déjà inscrit."]},{v:381,d:"2026-11-20",l:["Annuaire (avec le SQL 153) : l’option « Séminaristes visibles seulement par les membres connectés » est prête. Elle ne change rien tant qu’on ne la coche pas : page « Annuaire », cadre « Administration · visiteurs non connectés » (administration seulement). Cochée, un visiteur ou un robot ne reçoit plus aucun séminariste (ni nom, ni année, ni diocèse) ; il voit l’équipe et les professeurs. Les membres connectés voient tout, comme avant. Les textes (accord à la première connexion, Confidentialité, Mes coordonnées) suivent l’option.","Confidentialité : durées de conservation effacées automatiquement par le serveur (vitesse 120 jours, journal de sécurité 400 jours, essais de connexion 1 à 2 jours, recherches web du plagiat 62 jours, plagiat 5 ans par défaut) ; autorité de contrôle : la Commission Malagasy de l’Informatique et des Libertés (CMIL), loi n° 2014-038, article 28."]},{v:380,d:"2026-11-20",l:["Sécurité (avec le SQL 152) : les fichiers envoyés par une personne non connectée (pièces d’une demande d’inscription, capture d’un paiement MVola) sont limités par le serveur : environ 30 par heure et 120 par jour, et un plafond d’espace (300 Mo pour les inscriptions, 100 Mo pour les paiements). Un robot ne peut plus remplir l’espace gratuit du site ; une vraie demande n’est jamais gênée.","Lisibilité : les petits titres en capitales (rubriques, jours de l’agenda, devise, badges) font au moins 12 pixels.","Confidentialité : la page dit maintenant que les vignettes et les vidéos viennent de YouTube (Google)."]},{v:379,d:"2026-11-20",l:["« Aide » (épreuves de notre ami sur téléphone) : « Comment demander une attestation de scolarité ? » montre la carte « 🔒 réservé aux étudiants connectés : Me connecter », même sans « mon » ni « je ».","« Aide » comprend l’écriture SMS : « komen je fai pr minskrir o seminer » mène à l’inscription (komen, kel, ke, ki, fo, o, pr, minskrir, inskri, stp, svp, bcp…).","Question de suite : après « Comment demander une attestation ? », « et pour le relevé de notes ? » devient « Comment demander le relevé de notes ».","Deux demandes dans une question : les deux réponses sont fermées l’une sous l’autre, pour qu’on les voie toutes les deux sur l’écran du téléphone.","« Je ne veux plus recevoir les notifications sur mon téléphone » mène à la nouvelle fiche « Arrêter les notifications sur mon téléphone » (et non plus aux emails).","Quand « Aide » est sûre de sa réponse, elle ne cite plus les mots qu’elle ignore (politesse, villes…). « Quelles sont les conditions pour entrer ? » est compris même au milieu d’une longue question. « Quel âge faut-il ? » est compris sans accent.","« Aide » ne répond plus avec assurance à des sujets qui ne sont pas ceux du site : la température, un compte en banque, installer WhatsApp ou une autre application.","« Changer mon mot de passe » (visiteur) : « réservé aux personnes connectées », et non plus « aux étudiants ».","Statistiques (avec le SQL 151) : aucun chiffre de 1 ou 2 personnes n’est publié, ni dans la base, ni dans le site, ni dans la copie du programme. Une origine dont une année a moins de 3 séminaristes ne montre que son total (l’année ne peut plus se retrouver par soustraction) ; les petits regroupements « Autres » de moins de 3 ne sont pas publiés.","Dates des fiches : « Trouver un livre à la bibliothèque », « Voir tous les livres du GSTF » et les modes d’emploi « Apparence » et « Sakafom-pitiavana » portent la date de leur dernière modification."]},{v:378,d:"2026-11-20",l:["« Aide » : quand elle a déjà une réponse directe (par exemple « 📚 40 livres du thème Morale »), l’encadré « 🔎 Aussi dans le site » se place EN DESSOUS, et non plus au-dessus : sur téléphone, la vraie réponse n’est plus poussée hors de l’écran. Une demande de livre ne propose plus de cours dans cet encadré. Quand l’encadré reste en haut (« où est l’article… »), il se place juste sous la question en cours, et non plus au-dessus de toute la conversation."]},{v:377,d:"2026-11-20",l:["Vie privée (avec le SQL 150) : « Le Séminaire en chiffres » ne publie plus aucun groupe de moins de 3 séminaristes. Une année de moins de 3 est montrée sans l’année (« année non précisée ») ; une congrégation ou un diocèse de moins de 3 est compté dans « Autres congrégations » ou « Autres diocèses ». Les totaux (260 étudiants, par année) ne changent pas.","« Aide » : « J’ai reçu un SMS qui demande mon mot de passe au nom du Séminaire » mène de nouveau à « message suspect » (et non plus au dépannage du mot de passe). « Aide » comprend aussi l’âge pour entrer, l’agenda dans le téléphone, vérifier si son téléphone marche avec le site, les photos de la fête patronale (« Événements inoubliables ») et « retta » (les frais, en italien).","Téléphone : les boutons FR · EN · IT sont plus grands (32 pixels), plus faciles à toucher. Les champs du formulaire d’intention, de la recherche d’articles, de l’annuaire et des cours ont une étiquette pour les lecteurs d’écran.","Les exemples d’identifiant montrent une forme inventée (xxxxxx@gstf-faliarivo.ovh), plus jamais un vrai compte. Chaque fiche de « Aide » corrigée porte sa nouvelle date."]},{v:376,d:"2026-11-20",l:["« Aide » : fiches corrigées. Les fiches du menu « Affichage », des réglages et du bandeau indiquent les langues FR, EN, IT. « Emprunter ou réserver un livre » signale le bouton « 📚 Voir tous les livres du GSTF (de A à Z) »."]},{v:375,d:"2026-11-19",l:["Sécurité (avec le SQL 149) : chaque nuit à 3 h 20, le site se contrôle lui-même : il se met à la place d’un visiteur inconnu et vérifie qu’il ne peut lire aucune donnée privée (étudiants, notes, présences, signatures, billets, demandes, réglages internes) ; il vérifie que la protection de détresse est en place et que la sauvegarde Google Drive a réussi depuis moins de 48 heures. S’il y a un problème, une alerte « 🚨 URGENT : sécurité du site » part au Père Préfet (e-mail, WhatsApp, notification), au plus une fois par jour. État du site montre le résultat de la dernière nuit. Aucune donnée n’est envoyée à une autre personne."]},{v:374,d:"2026-11-19",l:["« Aide » (contrôle de notre ami, 19 novembre, 22 h) : quand le vrai sujet de la question est un mot que le site ne connaît pas (« le prix de l’essence ») et que les autres mots sont trop généraux (« prix », « compte », « installer », « aujourd’hui »), « Aide » ne répond plus avec assurance : elle dit qu’elle n’est pas sûre.","« Qui est le préfet des études ? », « qui est l’économe ? » mènent à « Qui dirige le Séminaire ? ». Le dépannage « l’email du mot de passe n’arrive pas » ne s’ouvre plus que si la question parle de mot de passe. Le détour par l’agenda ne passe plus devant une fiche sûre (emploi du temps, photos des fêtes).","« Aide » comprend mieux : l’âge pour entrer, le quartier du Séminaire, tester son téléphone, mettre l’agenda dans son téléphone, les langues du site (« Le malgache n’est pas proposé pour le moment »). « Mes billets » mène à la carte des billets du Sakafom-pitiavana."]},{v:373,d:"2026-11-19",l:["Sakafom-pitiavana (avec le SQL 148) : chaque séminariste voit ses billets sur sa page (Mon espace › « 🎟 Mes billets du Sakafom-pitiavana ») : ses numéros, et pour chacun « à vendre », « vendu, argent à remettre » ou « payé » (espèces ou MVola), avec l’argent qui reste à remettre au Séminaire, la date, l’heure, le lieu et la date limite. Il ne voit que ses propres billets ; le nom de l’acheteur n’est jamais dans le site. La carte se met à jour dès que l’administration enregistre une vente ou un paiement."]},{v:372,d:"2026-11-19",l:["Langues du site : le malgache est retiré (décision du Père Préfet des études : le site ne maîtrise pas encore assez bien la langue). Le choix en haut montre FR, EN, IT ; un ancien choix « MG » revient au français. Le malgache reviendra après relecture et validation par le Père Préfet. Restent inchangés : l’heure de Madagascar, la CMIL, les fêtes malgaches, les articles et ressources écrits en malgache, et l’invitation du Sakafom-pitiavana.","« Aide » est plus prudente : elle n’affirme une réponse que si elle est sûre ; sinon : « Je ne suis pas sûr d’avoir compris votre question » avec ce qui s’en rapproche le plus. Une question hors sujet est arrêtée ; la carte « réservé aux étudiants » ne paraît que si la fiche réservée est vraiment la réponse.","« Aide » : « citer », « citation », « référence », « bibliographie », « bas de page » mènent aux normes de citation ; « examen final » ne mène plus aux notes ; la correction des fautes de frappe ne « corrige » plus un mot courant.","« Aide » : une phrase de détresse écrite en malgache est toujours reconnue ; la réponse (avec les numéros) est donnée en français.","État du site : le score de « Aide » est montré en deux parties : les questions qui ont servi à la régler, et un contrôle jamais vu (avec les questions hors sujet et le nombre de réponses fausses données avec assurance).","Fichier SQL 147 : efface les textes malgaches de l’apparence et des résumés d’actualités (il montre d’abord ce qu’il efface)."]},{v:371,d:"2026-11-19",l:["Saint du jour : la semaine autour du jour en haut (une pastille de la couleur liturgique par jour, un anneau doré pour les fêtes ; toucher un jour l’ouvre) ; « ✨ Prochaines fêtes » (les 4 prochaines fêtes et solennités) ; un bouton « Partager » ; l’en-tête ne se tasse plus sur un téléphone étroit ; les boutons « Veille » et « Lendemain » suivent la langue du site, même quand la liturgie est en italien."]},{v:370,d:"2026-11-19",l:["Saint du jour : la fenêtre prend la couleur liturgique du jour (vert, violet, blanc et or, rouge, rose), sur un fond parchemin ; le rang (Solennité, Fête, Mémoire) en petites capitales dorées ; un ornement ✠ ; les offices en liste comme dans un bréviaire, avec leur moment (le matin, vers midi, le soir…), l’office de maintenant mis en valeur ; boutons de fermeture et de navigation plus discrets. Fêtes de la Vierge Marie (Immaculée Conception, Assomption…) : l’article de la fête, et non celui d’une congrégation du même nom.","Saint du jour (le soir) : après 18 h, la fenêtre le dit tout en haut ; « Demain » au lieu de « Aujourd’hui » ; « Lectures de demain » ; deux blocs clairs : « 🌙 Ce soir : Vêpres, Complies » et « ☀️ Demain : tous les offices » ; titre plus petit sur téléphone ; boutons « ‹ Veille » et « Lendemain › » ."]},{v:369,d:"2026-11-19",l:["Bibliothèque : trois bibliothèques : « 🏛 GSTF Bibliothèque » (prêt), « 📖 GSTF Usuel » (sur place seulement) et « 🏫 Bibliothèque de l’UCM » (pour information : ces livres s’empruntent à l’UCM). Trois boutons pour chercher dans chacune. Sous chaque livre : où il se trouve (bibliothèque, rayon, cote) et sa disponibilité.","Pour ajouter une liste de livres (Excel, Word, PDF ou photo), on choisit d’abord la bibliothèque. Au départ, les livres « sur place » sont dans l’Usuel, tous les autres dans la GSTF Bibliothèque. Avec le SQL 146."]},{v:368,d:"2026-11-19",l:["Bibliothèque : 70 nouvelles ressources en ligne gratuites (encycliques, documents du Saint-Siège, Pères de l’Église, philosophie, spiritualité, revues, Madagascar), rangées selon les 16 thèmes de la page Bibliothèque. Elles arrivent cachées : dans « 🌐 Ressources en ligne », le ou la bibliothécaire les ouvre et clique « ✓ Valider et publier ». Avec le SQL 145."]},{v:367,d:"2026-11-19",l:["Inscription : le numéro de téléphone de l’étudiant est obligatoire (comme l’email personnel), aussi bien dans l’inscription en ligne que dans « Nouvelle inscription » de l’administration.","Étudiants déjà inscrits : jusqu’au 31 décembre, à chaque connexion, le site demande le téléphone et l’email personnel s’ils manquent (« Plus tard » est possible, mais la demande revient à la connexion suivante)."]},{v:366,d:"2026-11-19",l:["Sakafom-pitiavana : le nombre de billets se choisit par classe : L1, L2 et L3, internes (séminaristes des 9 diocèses) et externes (religieux des congrégations), et pour le Père Préfet ; « Répartir les billets » les remet à tous d’un coup, avec des numéros qui se suivent.","Sakafom-pitiavana : sous chaque vendeur, « 📲 Confirmer ses paiements sur WhatsApp » ouvre WhatsApp avec le message déjà écrit (billets payés, espèces ou MVola, total reçu, billets encore à payer), vers le téléphone de sa fiche ; il suffit d’appuyer sur « Envoyer ». Gratuit ; rien n’est gardé sur l’acheteur."]},{v:365,d:"2026-11-19",l:["Sakafom-pitiavana : « 📋 Liste de contrôle » pour l’entrée, le jour de l’événement, faite à partir des billets : un numéro par ligne (du n° … au n° …), le responsable (« Fr. » et ses prénoms), « Payé » (espèces ou MVola, d’après le site), puis « Entrée ✓ » et « Observation » à remplir à la main ; 40 lignes par page A4 et un total à la fin.","Sakafom-pitiavana : enveloppes au style du billet. Formats : C6 162 × 114 mm (conseillé), DL 220 × 110 mm, C6/5 229 × 114 mm, C5 229 × 162 mm, carrée 120 × 120 mm, ou un autre format aux mesures libres. Trois modèles : « Rubans rouge et bleu », « Sobre » (fond blanc, pour les imprimantes qui laissent une marge) et « Classique ». Les couleurs du billet et des enveloppes se changent (deux couleurs et le fond, dans « ⚙️ Réglages » › « Couleurs »). Le même numéro que le billet ; un avertissement si l’enveloppe est trop petite pour le billet (99 × 105 mm) ; un aperçu dans la rubrique."]},{v:364,d:"2026-11-19",l:["« Quoi de neuf ? » s’ouvre en haut : la dernière version s’affiche en premier (avant, la fenêtre descendait jusqu’au bouton « Fermer », tout en bas)."]},{v:363,d:"2026-11-19",l:["Sakafom-pitiavana : nouveau billet, d’après le modèle de l’an passé (textes inchangés) : 6 billets par feuille A4 paysage ; le recto et le verso s’impriment par deux boutons séparés. Sur chaque billet, « Responsable : Fr. » suivi des prénoms complets du séminariste et son téléphone s’impriment tout seuls ; la date s’écrit « Ny alahady 23 May 2027 » ; au verso : le logo, la photo du Séminaire et « Tél : 038 21 220 21 / 034 92 920 77 ». Le sens du verso se règle (à l’envers comme l’an passé, ou à l’endroit)."]},{v:362,d:"2026-11-19",l:["Appel (décisions du Père Préfet) : le professeur note seulement les absents (un bouton « Absent » ; plus de P, R, E) ; chaque séance dure 2 h ou 4 h ; la liste suit l’ordre de la fiche de présence. Les heures d’absence sont comptées : moins de 26 h de présence sur 30 h (52 h sur 60 h pour la Dogmatique spéciale) : pas d’examen ; « ⚠️ à la limite » et « ⛔ pas d’examen » sont signalés. Avec le SQL 144.","« 🖨 Fiche de présence » au modèle du Séminaire (n°, nom et prénoms, signatures ; ligne vide pour un étudiant parti) et « 🖨 Liste pour l’examen ».","Mon espace (séminariste) : « 🕘 Mes absences », cours par cours, avec le droit à l’examen.","Sur téléphone : l’appel en cartes (n°, nom en entier, « Absent », heures, note) ; la Bibliothèque, chaque livre sur toute la largeur, la fiche du livre lisible, plus de texte coupé lettre par lettre."]},{v:361,d:"2026-11-19",l:["« Aide » : le bouton devient « ♡ Je vous souhaite tout le bien · Besoin d’aide ? » (en anglais et en italien selon la langue du site) ; plus grand et plus facile à toucher, le texte grandit avec « Aa », sur deux lignes propres sur un téléphone étroit. Au clic, rien ne change : la réponse pour parler à quelqu’un, sans rien taper ; rien n’est enregistré."]},{v:360,d:"2026-11-19",l:["« Aide » : une salutation avant la question (« Bonjour mon père, pouvez-vous m’aider ? », « Bonjour, je voudrais une attestation ») ne détourne plus la réponse."]},{v:359,d:"2026-11-19",l:["Bibliothèque, saisie d’un livre : les règles de saisie en haut du formulaire ; l’auteur et l’éditeur se proposent tout seuls dès les premières lettres ; « Ce livre existe déjà : ajouter un exemplaire ? » avant de créer une fiche en double ; l’ISBN est vérifié (chiffre de contrôle) ; un titre qui contient une année, « éd. » ou un éditeur est signalé ; l’année doit avoir 4 chiffres.","Gestion de la bibliothèque : « ✍️ À compléter » (livres sans auteur, éditeur, année, cote ou rayon) et « 👤 Auteurs » (les auteurs écrits de plusieurs façons, à fusionner en un clic : réservé à l’administration).","« Aide » : « Pouvez-vous m’aider ? Je n’arrive pas… » répond à la vraie question ; « ok merci » ; « Je ne veux pas recevoir les notifications » ; deux demandes reliées par « et » (« voir mes notes et demander une attestation ») ; « fepetra », « hidirana ». Les 32 questions réelles de notre ami font partie de l’examen : 32/32."]},{v:358,d:"2026-11-19",l:["Bibliothèque : 71 ressources en ligne, gratuites et légales (Catéchisme, Vatican II, Code de droit canonique, encycliques, Pères de l’Église, saint Thomas, revues, portails). Filtre « 🌐 En ligne · gratuit » et « Revues » ; quand on cherche « catéchisme » ou « Lumen gentium », la ressource en ligne apparaît d’abord ; sous un livre papier qui existe en ligne, « 🌐 Lire aussi le texte officiel en ligne ». Avec le SQL 143.","« Aide » : « Pas dans nos rayons, mais disponible gratuitement en ligne : … ».","Le ou la bibliothécaire gère les ressources (Gestion › « 🌐 Ressources en ligne ») : ajouter, modifier, cacher, « ✓ Vérifié » ; les liens non vérifiés depuis 6 mois sont signalés."]},{v:357,d:"2026-11-19",l:["Carte « porte » : un visiteur qui pose une question personnelle d’étudiant (« mon relevé », « mon mémoire ») lit « Cette démarche est réservée aux étudiants connectés » avec [Me connecter] ; après la connexion, la bonne fiche s’ouvre.","Un parent qui demande les notes de son fils lit que les notes sont personnelles, avec le secrétariat et le rendez-vous. Chaque fiche répond maintenant à son propre titre (deux fiches en double retirées)."]},{v:356,d:"2026-11-19",l:["« Aide » connaît les cours du site : « ma note de christologie » parle de vos notes (visiteur : « les notes sont personnelles, connectez-vous » ; séminariste : publiée ou non, avec le lien ; administration : où les trouver), « livres de christologie » de la bibliothèque, « qui enseigne la christologie ? » du cours, « TP de christologie » des devoirs.","« Aide » ne montre jamais les notes d’une autre personne, et dit clairement qu’une action (publier des notes…) est réservée aux professeurs et à l’administration.","« Aide » comprend l’écriture SMS (« cmt voir mé note »), une négation (« je ne veux pas m’inscrire, je veux annuler ma demande ») et la suite d’une conversation (« et pour la L3 ? »).","Réponses directes : durée du prêt et horaires de la bibliothèque, saint du jour, équipe formatrice, Sakafom-pitiavana, fêtes de Noël et de l’Avent dans l’agenda.","Nouvelles fiches pour les familles (« mon fils est séminariste »), pour annuler une demande d’inscription., pour une carte perdue, pour une absence.","Question envoyée au secrétariat : « sera lue à la réouverture, aujourd’hui à 14 h » (ou « demain à 8 h », « lundi à 8 h »), en tenant compte des jours fériés malgaches ; lien « Corriger et renvoyer » si l’adresse est fausse. Bouton « ♡ Je ne vais pas bien » plus visible."]},{v:355,d:"2026-11-19",l:["« Aide » lit le calendrier des rendez-vous : « le Préfet est-il libre aujourd’hui ? » (ou demain) répond directement si le Père Préfet reçoit ce jour-là, avec les créneaux libres, puis les prochains jours avec des places et un bouton « Prendre rendez-vous ». Aucun nom n’est montré.","« Je suis perdu, je ne sais plus quoi faire » : la question à choix propose d’abord « 🤍 Ce n’est pas le site : j’ai besoin de parler à quelqu’un » (réponse avec des personnes ; rien n’est enregistré). ","Une question qui nomme le Préfet ou le Recteur mène d’abord aux fiches qui parlent de lui (et non à une fiche qui le cite en passant). Nouvelle fiche « Rencontrer le Père Recteur » (par le secrétariat). Aussi en anglais et en italien (« available »…)."]},{v:354,d:"2026-11-19",l:["« Aide » lit aussi la liste des cours : « quel professeur donne le cours de Trinité ? » donne directement le cours, l’année, le semestre et le professeur (même sans accent ou avec une petite faute, et sans Internet). « Y a-t-il un examen la semaine prochaine ? » montre les dates de l’agenda."]},{v:353,d:"2026-11-19",l:["« Aide » répond aussi sans Internet : son code et ses 490 réponses sont gardés sur le téléphone dès la première visite ; les livres se cherchent dans la copie du catalogue gardée sur le téléphone, et l’agenda dans celui déjà ouvert (avec la date de la copie)."]},{v:352,d:"2026-11-19",l:["« Aide » agit au lieu d’expliquer : « Montre-moi les livres de morale », « as-tu un livre sur saint Augustin ? » : elle cherche aussitôt dans le catalogue et montre les livres (titre, auteur, année, disponible ou prêté avec la date de retour, cote) avec « 📌 Réserver » pour un livre prêté ; « les événements de cette semaine », « quand est la prochaine récollection ? » : elle montre l’agenda. La fiche « comment faire » vient seulement en complément."]},{v:351,d:"2026-11-19",l:["« Aide » dépanne pas à pas : pour 11 pannes courantes (connexion refusée, email « mot de passe oublié » qui n’arrive pas, notes invisibles, devoir qui ne s’envoie pas, livre impossible à emprunter, paiement MVola non reconnu, page blanche, notifications, demande d’attestation, lenteur, second code), elle examine l’appareil et le compte, dit où est le blocage, puis propose les solutions dans l’ordre avec « C’est réglé » / « Pas encore », et enfin un rapport complet au secrétariat.","« Aide » se souvient des 15 dernières minutes, sur l’appareil seulement : à « ça ne marche pas », elle montre le message d’erreur qui vient d’apparaître (ex. « Fichier refusé : 25 Mo au plus ») et la solution.","Avec le SQL 142, « Aide » vérifie le compte de la personne connectée, et seulement le sien : notes saisies et date de publication, prêts en retard, devoirs à rendre, demandes en cours… (des oui/non et des nombres, jamais une note)."]},{v:350,d:"2026-11-18",l:["Nouvelle rubrique Administration › « Sakafom-pitiavana » (avec le SQL 141) : réglages tous modifiables (date, heure, lieu, prix, téléphones, numéros, textes français et malagasy) ; billets numérotés recto-verso (4 par feuille A4, talon détachable) et enveloppes avec le même numéro ; feuille d’essai ; carte A5 en français et en malagasy ; image carrée pour WhatsApp et Facebook.","Répartition des billets : un nombre par étudiant actif (3 par défaut, modifiable avant de répartir ; ensuite « ＋ billet(s) de plus » ou ✕ pour chacun), rangés par diocèse, et des plages pour le Père Préfet ou d’autres vendeurs ; le nom et le téléphone du vendeur, repris de sa fiche d’inscription, s’impriment tout seuls sur ses billets (« Tompon’andraikitra »).","Suivi des ventes : vendu, payé en espèces ou par MVola, totaux par diocèse et montants ; le nom des acheteurs n’est jamais dans le site."]},{v:349,d:"2026-11-18",l:["« Aide » (examen de l’ami relecteur sur la v348) : « écrire au séminaire » mène à « Contacter le Séminaire » (la fiche sur la majuscule de « Séminaire » ne répond plus qu’à l’orthographe) ; « ibidem », « op. cit. » mènent aux normes de la deuxième citation ; « rentrée » à l’inscription ; « photos de la fête » aux Événements inoubliables ; « quel saint fête-t-on ? » au saint du jour."]},{v:348,d:"2026-11-18",l:["Prières : « 🕯 Mode chapelle » pour prier ensemble avec le téléphone : écran sombre, grand texte, rien qui distrait, l’écran reste allumé, rappel « mettez votre téléphone en silencieux ».","Portail Étudiant : cadre « 🔐 Mes données » (loi 2014-038) : télécharger ce que le site sait de moi, demander une correction ou la suppression de mon compte (message au secrétariat avec un numéro).","Abonnement aux articles (avec le SQL 140) : au plus un email de confirmation par adresse et par jour.","Administration › « Aide » › Questions des visiteurs : export aussi en .txt.","Confidentialité : l’identifiant de l’appareil n’est plus créé pour chaque visiteur, seulement au moment d’une connexion ; la page « Pages » vide n’est plus affichée."]},{v:347,d:"2026-11-18",l:["Sécurité (avec le SQL 139) : un visiteur non connecté ne peut plus lire les identifiants de connexion de l’équipe (« publié par », « créé par », éditeurs des pages…) ; les personnes connectées ne voient aucun changement.","Sécurité (SQL 139) : le formulaire de contact, l’abonnement aux articles, le rendez-vous sans compte et la demande d’inscription ne peuvent plus servir à faire envoyer des emails en masse (au plus 6 envois par heure depuis un appareil, 3 par jour vers une même adresse, 150 par jour en tout) : le quota Gmail reste disponible pour les vrais emails.","État du site › Test réel « visiteur non connecté » : vérifie aussi que les colonnes d’identifiants restent cachées."]},{v:346,d:"2026-11-18",l:["« Aide » : la réponse de détresse est donnée dans la langue de la phrase (anglais, italien ou français), quelle que soit la langue choisie pour le site ; le bouton « 🤍 Je ne vais pas bien » répond dans la langue du site.","Application téléphone : les articles, homélies et pages du Séminaire déjà lus restent lisibles sans Internet (les 10 derniers articles ou homélies), avec « Lu hors connexion · copie du … » ; la vidéo d’une homélie se regarde quand on a Internet.","Articles : en enregistrant un article dont le titre existe déjà (ex. plusieurs « Méditation »), le site avertit et propose un titre propre ; un second clic garde le titre quand même."]},{v:345,d:"2026-11-18",l:["« Aide » : nouveau bouton discret « 🤍 Je ne vais pas bien » : la réponse de détresse s’affiche sans rien taper, et rien n’est enregistré.","« Aide » reconnaît aussi la détresse dite en malgache (la réponse est donnée en français) ; avec le SQL 138, le serveur refuse aussi de garder une phrase de détresse, et celles déjà enregistrées sont effacées.","« Mes cours aujourd’hui » ouvre « Ma semaine » du Portail Étudiant (avant : une page absente).","Connexion : les anciennes fonctions de recherche d’identifiant sans mot de passe (supprimées par le SQL 127) ne sont plus appelées."]},{v:344,d:"2026-11-18",l:["Authenticité des documents (avec le SQL 137) : la page de vérification par QR code s’affiche en français, en anglais ou en italien (selon le téléphone, avec FR · EN · IT pour changer) ; une ligne en anglais sous chaque QR (« Verify authenticity… ») ; au plus 20 vérifications par minute depuis une même adresse (contre les essais à la chaîne) ; dans le registre des courriers, « 🔎 vérifié N fois, dernière le … » (jamais par qui) ; un document annulé dit depuis quand.","📶 Version légère : nouvelle page « aujourdhui.html », en texte seul (moins de 5 Ko) : liturgie du jour, 7 prochains événements publics, horaires, contact. Refaite par GitHub, lisible hors connexion ; lien en bas de chaque page et dans « Aide ». Pour Google : logo et pages Facebook et YouTube ajoutés à la fiche du Séminaire ; chaque événement public de la page légère est décrit pour Google."]},{v:343,d:"2026-11-18",l:["Statistiques de visites (avec le SQL 136) : le numéro de visite tiré au hasard sur l’appareil change tout seul après 13 mois, et n’est jamais relié à un compte (seulement « connecté » ou non). Chaque nuit, le détail des visites de plus de 25 mois est effacé et remplacé par les totaux du mois. La page Confidentialité le dit.","Lettres et attestations : sur téléphone, l’aperçu est la vraie feuille A4 en entier, réduite à la largeur de l’écran (plus rien n’est coupé à droite). « ⛶ Voir en grand » l’ouvre en plein écran : glisser à gauche et à droite, « + » et « − » pour agrandir, « Ajuster » ; en tournant le téléphone, la feuille se réajuste."]},{v:342,d:"2026-11-18",l:["Intentions de prière (avec le SQL 135) : la personne choisit elle-même « J’accepte que mon intention soit affichée » et « Avec mon prénom ». Sans son accord, « Afficher sur l’accueil » n’apparaît pas et la base refuse ; son choix ne peut pas être modifié ensuite. Une intention déjà affichée sans accord est retirée de l’accueil.","« Aide » : la clé envoyée avec chaque question ne dure plus qu’une visite ; les clés déjà enregistrées sont effacées (SQL 135), puis chaque heure après 2 heures. On ne peut plus relier les questions d’un même téléphone d’un jour à l’autre. Seuls les signalements, voulus par la personne, gardent une clé pour lui dire « corrigé »."]},{v:341,d:"2026-11-18",l:["Relecture du cahier des charges : une détresse (en français, malgache, anglais et italien), un deuil, une peine confiée ou une question qui nomme une autre personne ne sont plus envoyés du tout au serveur, pas même masqués. La page Confidentialité dit exactement ce qui est envoyé : la question masquée, la page et le type de compte, sans nom ; la conversation reste sur l’appareil. La réponse de détresse attend de l’administration un numéro joignable à toute heure. « Aide » ne donne jamais les coordonnées d’une personne, quelle que soit la langue. Le score de l’examen de « Aide » est affiché dans État du site."]},{v:340,d:"2026-11-18",l:["Pour que les étudiants trouvent eux-mêmes au lieu d’aller au secrétariat : « Où en est ma demande ? » lit l’état de l’attestation et du relevé ; « Mes cours aujourd’hui » lit l’emploi du temps ; « Ce que je peux faire moi-même en ligne » ; avant d’écrire au secrétariat, « Aide » propose de faire la démarche soi-même quand elle existe.","« Aide » ne donne jamais le numéro ou l’adresse d’une personne (le secrétariat transmet). Après un message au secrétariat : date et heure de Madagascar, et, s’il est fermé, la réouverture. Nouvelles réponses à compléter par l’administration : délai de réponse du secrétariat, horaires des bureaux pendant les vacances, personnes vers qui se tourner en détresse (reprises dans la réponse de détresse), signaler un abus.","Administration › « Aide » › « Questions des visiteurs » : réponses à revérifier (plus d’un an) et « 🖨 Bilan du mois pour le Père Recteur » (une page, aucune question ni aucun nom). Meilleures réponses : laudes et vêpres, fin du semestre, page blanche, texte trop petit, « le site rame »."]},{v:339,d:"2026-11-18",l:["« Aide » devient une conversation : vos questions précédentes restent au-dessus (repliées, à relire d’un toucher) ; « 🗑 Nouvelle conversation » ; tout s’efface à la déconnexion et ne quitte jamais l’appareil.","« Aide » lit vos propres données, sans rien changer : « quand dois-je rendre mes livres ? » montre vos emprunts (et les retards) et vos réservations ; « mon prochain rendez-vous » montre votre rendez-vous avec le Père Préfet.","Plusieurs questions dans un même message : une réponse pour chacune. Sous une réponse : « Souvent demandé ensuite », « 📋 Copier » et « 💬 Envoyer sur WhatsApp ». « Poser ma question au secrétariat » reprend les questions déjà posées, pour que le secrétariat comprenne tout de suite (la personne peut les retirer avant d’envoyer).","Une personne en détresse (« je veux mourir », « on me menace »…) reçoit d’abord une parole et une personne (Père Préfet, Père Recteur, directeur spirituel, secrétariat), jamais une fiche ; sa phrase n’est pas enregistrée.","Administration › « Aide » › « 📊 Questions des visiteurs » : bilan automatique des 7 derniers jours (questions, réponses trouvées, jugées utiles, réponses qui ont déçu) et liste de ce que « Aide » ne sait pas encore, avec « Compléter »."]},{v:338,d:"2026-11-18",l:["« Aide », d’après un essai extérieur de 38 questions : plus de fausse alerte « mot de passe » (« passé », « et », un point après « mot de passe ») ; plus de corrections absurdes (« remboursé » → « rebours ») ni de « je ne connais pas « mais » » ; une plainte, une urgence ou « parler à une personne » reçoit des excuses, le téléphone et les heures du secrétariat et le bouton pour lui écrire (plus jamais « Faire un don ») ; une demande sans sujet (« j’ai un problème depuis ce matin ») reçoit la question à choix ; « merci » reçoit « Avec plaisir » ; meilleurs aiguillages (compte bloqué, erreur 500, site qui ne charge pas, supprimer mon compte, moyens de paiement, payé deux fois, envoyer de l’argent) ; deux nouvelles réponses : « Que veut dire ce message d’erreur ? » et « Utiliser le site depuis l’étranger »."]},{v:337,d:"2026-11-18",l:["Accueil : le fond du cadre « Bonjour » (personnes connectées) est réglable. Administration › Apparence › « Cadre « Bonjour » » : 9 modèles (Bordeaux, Vert liturgique, Bleu marial, Violet, Or ancien, Bleu nuit, Vatican jaune et blanc, Parchemin, Blanc) ou une couleur choisie à la main ; le texte passe en blanc ou en foncé tout seul pour rester lisible ; aperçu sur la page. Chacun peut aussi choisir un modèle pour son appareil (« Affichage » › « Fond d’écran »), sans pouvoir inventer une couleur.","« Aide » compare aussi votre question à 495 exemples de questions réelles possibles (75 réponses). Mesuré sur 4 examens, dont 2 jamais vus pendant la mise au point : aucune question perdue ; 47 → 52 sur 60 à l’aveugle, 28 → 36 sur 40 inédites, 203 → 211 sur 214."]},{v:336,d:"2026-11-18",l:["« Aide » ne choisit plus au hasard quand deux réponses sont à égalité (moins de 10 % d’écart) et qu’aucune ne reprend les mots de la question (par exemple « candidat ») : elle demande « Votre question peut avoir deux sens. Lequel cherchez-vous ? » et montre les deux, plus une troisième possibilité. Cela reste rare : 2 questions sur 106 dans l’examen de « Aide »."]},{v:335,d:"2026-11-18",l:["« Aide » comprend mieux trois sortes de questions : un deuil (« mon père est décédé », « nodimandry… ») mène à « Confier une intention de prière », avec une phrase de compassion ; les heures de la bibliothèque mènent à la fiche de la bibliothèque (et non plus au secrétariat) ; « gardez-vous mon adresse email ? » mène à « Confidentialité » (et non plus à l’adresse du Séminaire)."]},{v:334,d:"2026-11-18",l:["« Aide » › « 📊 Questions des visiteurs » › « 📤 Exporter toutes les questions posées » : un fichier pour Excel avec les vraies questions des 6 derniers mois (date, question, page, type de compte, réponse proposée, jugée utile), masquées une seconde fois, sans nom, sans compte, sans appareil. Il sert à mesurer « Aide » sur des questions que personne n’a inventées."]},{v:333,d:"2026-11-18",l:["Administration › Apparence › « Fond des pages » : 8 choix prêts à l’emploi (Parchemin, Ivoire, Sable doré, Lin, Vatican jaune et blanc, Rose pâle, Blanc, ou celui du thème) ; on voit le résultat tout de suite. Le fond et la couleur des cadres se règlent aussi à la main. Le contrôle de lisibilité vérifie aussi le texte dans les cadres.","L’application du téléphone et la page « hors connexion » s’ouvrent directement avec le fond choisi (plus d’éclair de l’ancien fond).","Chacun peut choisir son fond d’écran parmi ceux proposés : menu « Affichage » › 🎨 « Fond d’écran » (sur cet appareil seulement). Seule l’administration règle les couleurs à la main.","Lisibilité : le gris des textes secondaires est plus foncé (au moins 5 : 1 sur tous les fonds) ; boutons WhatsApp d’un vert plus foncé ; les étiquettes des couvertures d’articles grandissent avec « Aa ».","« Aide » : nouvelle réponse « Je n’arrive pas à me connecter à mon compte » (aussi en anglais) ; « le site est en pause » mène à la bonne réponse ; les codes reçus par SMS sont masqués eux aussi ; le diagnostic ne parle plus de « numéro d’étudiant » pour se connecter."]},{v:332,d:"2026-11-18",l:["Décisions du Préfet des études (SQL 133) : l’économe ne voit plus les notes ni les fiches complètes des étudiants ; son portail montre une liste simple (nom, classe, diocèse ou congrégation, matricule). L’économat reste entièrement à lui.","Sauvegarde des données sur le Google Drive chaque nuit au lieu de chaque dimanche : au pire, on perd une journée au lieu d’une semaine.","Après une perte de la base (SQL 134) : Administration › Sauvegarde › « Recréer les comptes » crée d’un coup les comptes qui manquent, envoie les accès par email ou prépare les fiches à imprimer."]},{v:331,d:"2026-11-18",l:["« Aide » ne garde, ne répète et n’envoie jamais un mot de passe, un téléphone ou une adresse email écrits dans une question : ils sont masqués avant tout envoi (SQL 132 : masque aussi les anciennes questions). Si quelqu’un écrit son mot de passe, elle l’avertit.","Contre les faux messages : à la connexion et dans « Mot de passe oublié », un rappel que le Séminaire ne demande jamais le mot de passe ; nouvelle réponse « J’ai reçu un message suspect au nom du Séminaire ».","Diagnostic de l’appareil plus complet : date et heure du téléphone, ce qui est gardé pour lire sans Internet, navigateur et mémoire ; il distingue « pas d’Internet » et « le site ne répond pas ».","Question vague (« ça ne marche pas ») : « Aide » demande de quoi il s’agit au lieu de deviner.","« Aide » passe un examen de 93 questions réelles (français, sans accents, fautes, anglais, italien, langage parlé) à chaque version : 99 % de bonnes réponses en premier ; « où est ma carte » ne mène plus à l’adresse du Séminaire."]},{v:330,d:"2026-11-17",l:["Important (SQL 131) : le serveur connaît désormais l’année académique même si les dates de l’année n’ont pas été enregistrées. Avant : la date de publication des notes n’était pas respectée, et « Remettre le relevé » aurait refusé avec « Année académique non réglée ».","« Aide » : bouton « 🩺 Faire le diagnostic de mon appareil » (Internet et site, version, affichage, notifications, langue, compte, en une fois) ; elle comprend mieux « pas d’internet », « quand sont les examens », « ça ne marche pas ».","« Aa » agrandit maintenant presque tous les textes (boutons, petits titres, étiquettes, fiches des cours) ; l’impression ne change jamais (relevés sur une page).","Articles sans Internet : « 📴 Pas de connexion » au lieu de « Aucun article publié ».","Le 21 août : Bienheureuse Victoire Rasoamanarivo (mémoire obligatoire, propre de Madagascar).","Sauvegarde : noms des tables en français et texte exact ; Année académique : rappel quand les dates ne sont pas enregistrées.","Sécurité (SQL 130) : un réglage interne de plus caché aux visiteurs."]},{v:329,d:"2026-11-17",l:["Sécurité : le lecteur de PDF du site est protégé contre les PDF piégés (faille CVE-2024-4367) ; le lecteur Excel est mis à jour (SheetJS 0.20.3).","« Aide » (SQL 128) : les fiches de l’administration, des professeurs, des éducateurs et des bibliothécaires ne sont plus dans un fichier que tout visiteur pouvait télécharger ; elles sont dans la base, et chacun ne lit que celles de son rôle. Chacun ne reçoit plus que les réponses de son rôle. « Aide » se charge deux fois plus vite.","« Aide » : « Prendre rendez-vous » et « Faire un don » mènent au bon onglet ; « entrer au Séminaire » répond sur l’admission, plus sur la connexion ; trois réponses corrigées (sans Internet, Économat, heures de la bibliothèque).","Formulaires (SQL 129) : intentions de prière et demandes de livres limitées sur le serveur lui-même contre les envois en masse.","Page Confidentialité mise à jour : hébergement GitHub Pages, services extérieurs nommés, questions à « Aide », mesure de vitesse, copie gardée sur le téléphone, durées."]},{v:328,d:"2026-11-17",l:["Sans Internet : les prières, l’agenda, la bibliothèque, les articles, les actualités et l’emploi du temps déjà ouverts une fois restent lisibles. Le site montre tout de suite la dernière copie gardée sur le téléphone, avec un bandeau « 📴 Hors connexion » qui dit de quand elle date. Avant : chaque page attendait 7 secondes, puis restait vide ou « Chargement… ».","L’application garde la page dès la première visite (avant : il en fallait deux).","Ne sont jamais gardés : notes, présences, signatures, réglages internes. Tout est effacé du téléphone à la déconnexion."]},{v:327,d:"2026-11-17",l:["Sécurité (SQL 127) : se connecter avec son nom, son téléphone ou son adresse personnelle vérifie le nom ET le mot de passe ensemble sur le serveur ; l’identifiant d’un étudiant n’est plus donné à quelqu’un qui ne connaît pas son mot de passe. Deux étudiants du même nom : le mot de passe suffit à les distinguer. Trop d’essais avec un même nom : 15 minutes d’attente.","Réglages : les visiteurs non connectés ne voient plus qui a modifié un réglage, ni les réglages internes (plagiat, évaluation, Facebook…).","iPhone : la page ne se zoome plus toute seule quand on touche un champ (champs en 16 px sur iPhone)."]},{v:326,d:"2026-11-17",l:["Lisibilité (analyse de tous les onglets, en mode clair et sombre, ordinateur et téléphone) : les textes dorés (dates, petits titres « À la une », chiffres, règlement) sont d’un or plus foncé en mode clair ; boutons WhatsApp et Facebook plus lisibles ; le menu « Partager » ne sort plus de l’écran du téléphone ; la jauge d’espace de stockage n’affiche plus « NaN ».","Appel et notes : pas d’appel pour une séance à venir (les cases de présence attendent le jour de la séance ; les notes restent modifiables) ; la première colonne s’appelle « Matricule ».","Menus : les titres des groupes (Mes raccourcis, Espace du Séminaire, Étudiants, Professeurs, Notes et documents, Communication, Paramètres ; Programme, Calendrier, Outils de l’étudiant) sont en couleur du Séminaire et en gras, plus lisibles."]},{v:325,d:"2026-11-17",l:["Signature et cachet : à l’impression, ils sont exactement à la même place et à la même taille que dans l’aperçu de « Ma signature » (le cachet suit la signature quand on l’a déplacée)."]},{v:324,d:"2026-11-17",l:["Bibliothèque › « Remettre en ordre le catalogue » : sous chaque doublon, une case « Exemplaires » pour mettre le nombre réel d’exemplaires sur les rayons (proposé : la somme des fiches).","Résumés et couvertures : le compteur distingue les livres sans résumé et ceux dont le titre a été corrigé (résumé vérifié de nouveau)."]},{v:323,d:"2026-11-17",l:["Administration › Étudiants : le numéro s’affiche sous le nom (« sans numéro » en orange s’il manque) ; la recherche trouve un nom sans accents ou un numéro (« 6 ») ; les boutons (Enregistrer, Nouveau mot de passe, Retirer…) sont rangés en colonne et restent visibles sans faire défiler le tableau. Même rangement pour les enseignants.","Calendrier de réserve : 1er semestre jusqu’au 3 février, 2e semestre à partir du 8 février 2027.","Bibliothèque, import Excel : les colonnes de la fiche de la bibliothèque sont reconnues (Emplacement sur les Rayons, Édition, Date d’édition, Catégories ; lieu et nombre de pages dans la remarque) ; les lignes identiques deviennent les exemplaires d’un même livre ; un livre déjà au catalogue (même cote, ou même titre et même auteur) est mis à jour au lieu d’être ajouté une 2e fois.","« Installer l’application » : si le téléphone ne propose plus sa fenêtre (déjà refusée, ou site ouvert dans WhatsApp / Facebook), le bouton explique quoi faire."]},{v:322,d:"2026-11-17",l:["Bibliothèque › Ajouter une liste de livres : nouveau bouton « 📊 Excel » (1re ligne : Titre, Auteur, Éditeur, Année, Cote…).","Études : les étiquettes « Incomplète (x/4) » des syllabus ne sont plus montrées au public, seulement aux professeurs et à l’administration ; dates du calendrier académique sur une ligne ; sur téléphone, le menu d’Études montre qu’il glisse de côté."]},{v:321,d:"2026-11-17",l:["Administration › Relevés : choix de la classe directement dans le cadre « Avant la délibération » (les boutons de remise ne sont plus grisés sans explication) ; phrase visible « Choisissez une classe » pour le tableau récapitulatif et l’archivage.","Bandeau en haut de la page « 📩 … demande(s) de relevé en attente » : un clic descend aux demandes.","Case « Rechercher (nom ou numéro) » au-dessus de la liste des étudiants."]},{v:320,d:"2026-11-17",l:["Relevés, décision du Préfet des études : pour l’administration, le relevé est toujours comme le définitif, prêt à imprimer (signature et cachet, sans filigrane ni mention ajoutée) ; pour les étudiants, le même relevé avec le filigrane « PROVISOIRE » tant qu’il n’est pas remis (sans signature : elle reste réservée à l’administration). Sur le relevé définitif : « Ce relevé n’est valable qu’avec son code d’authenticité, vérifiable en scannant le code QR. »","Administration › Année académique › Cours : nouvelle colonne « Classe » (L1, L2, L3) pour corriger la classe d’un cours ; confirmation demandée, refus si le cours a déjà des notes ; rappel de l’emploi du temps."]},{v:319,d:"2026-11-17",l:["Relevés : la signature (et le cachet) n’apparaissent que sur le relevé définitif, remis ou archivé avec son code QR ; le relevé provisoire porte un grand « PROVISOIRE » en filigrane et la phrase « sans valeur officielle ».","Le code QR se place sous la date, à côté de la signature : le relevé tient sur une page.","Signature : le relevé prend d’abord la signature et le cachet de la personne connectée (une ancienne fiche au même nom ne passe plus devant) ; bouton « 🎨 Couleur, place et cachet » ; nouveau bouton « 📋 Coller le cachet »."]},{v:318,d:"2026-11-17",l:["Portail Professeur, Appel et notes : nouvelle colonne « Absences ce semestre » (absences à ce cours, séance du jour comprise ; en rouge à partir de 3) ; « Tous présents » et l’enregistrement demandent « Vous n’avez marqué aucun absent : confirmez-vous ? ».","Importer les notes d’une photo : la photo s’affiche à côté des notes lues ; les notes peu lisibles (1 ou 7, 3 ou 8…) sont encadrées en orange.","Le texte sous les boutons explique que tout s’enregistre seul ; le bouton « Enregistrer » sert après un import. Sur ordinateur, les onglets du portail vont à la ligne (plus de barre grise) ; le nom de l’enseignant n’est plus coupé."]},{v:317,d:"2026-11-17",l:["Accueil : petits titres du cadre « Bonjour » plus lisibles ; tout s’affiche au bout de 3 secondes (plus de trous sur les captures) ; la miniature de l’homélie se charge tout de suite ; un seul bouton « ⤴ Partager » par carte, qui ouvre le choix ; la méditation n’apparaît qu’une fois ; le logo des vignettes passe dans un coin ; « Liturgie de demain » le soir.","Administration : « 👁 Voir comme un visiteur » (cadre « Bonjour ») ouvre le site dans un nouvel onglet, sans connexion, tel que le voit un visiteur."]},{v:316,d:"2026-11-17",l:["Publications (articles, annonces, actualités, documents de cours, livres) : plus rien n’est coché d’avance pour l’envoi (email, notification, Facebook) : on coche à chaque fois ce qu’on veut envoyer.","Articles : avant qu’un PDF devienne téléchargeable par tout le monde, le site demande de confirmer qu’il ne contient ni téléphones, ni courriels, ni liste d’étudiants, ni notes ; il propose aussi de le réserver aux étudiants et professeurs, ou de choisir les destinataires. Un nom de fichier qui fait penser à un document interne (livret, liste, notes…) est signalé."]},{v:315,d:"2026-11-17",l:["Documents imprimés : partout la même adresse, www.gstf-faliarivo.ovh (relevés, attestations, lettres, livret, Word) ; le code QR garde l’adresse complète.","Livret académique : le mode d’emploi décrit la fabrication du livret sur le site (« Copier ce tableau » reste en secours) ; le tableau des effectifs prévus (1re → 2e, 2e → 3e) porte la mention « provisoire, à confirmer après le passage d’année » ; une partie sans titre imprimé montre son nom dans la liste."]},{v:314,d:"2026-11-17",l:["Téléphones : la Bibliothèque numérique ne sort plus de l’écran (le lien passe sous le titre) ; les longs noms se coupent au lieu de déborder ; téléphone couché : l’en-tête ne reste plus collé en haut ; le bouton « ↑ » disparaît (la barre du bas suffit) et « Aide » s’efface pendant qu’on fait défiler.","Le menu du haut montre par un fondu qu’il continue à droite ; « Voir l’autre actualité » au singulier ; le nom du Séminaire dans le pied de page a le style des titres."]},{v:313,d:"2026-11-17",l:["Pied de page : de nouveaux titres, avec une phrase qui explique (« La vie au Séminaire », « Le Séminaire en un clic », « Mon espace »), modifiables dans « ✏️ Modifier le pied de page » › « Titres des trois colonnes ». Bibliothèque et Agenda y sont ajoutés ; Prières et Événements inoubliables passent dans « La vie au Séminaire ». Le téléphone s’appelle d’un toucher ; textes plus foncés, plus lisibles au soleil ; sur téléphone, chaque colonne s’ouvre d’un toucher."]},{v:312,d:"2026-11-17",l:["« Administration » passe dans la barre du haut, après « Contact » (seulement pour l’administration) ; la barre verticale garde les 9 autres rubriques."]},{v:311,d:"2026-11-17",l:["Relevés fiables (SQL 126) : chaque relevé archivé est gardé tel qu’il s’imprime (document, moyenne, mention, crédits) ; il ne change plus, même si le modèle ou le signataire changent. Vérification : Administration › Relevés › « Relevés archivés figés ».","Avant la délibération (Administration › Relevés) : « Verrouiller les notes du 1er semestre » d’un coup ; « Essai de la remise » (rien n’est gardé) ; « Remettre les relevés du 1er semestre » : chacun avec son code QR, gardé tel qu’il est remis ; le Préfet seul peut annuler une remise, avec un motif. Les étudiants voient leurs notes dès la saisie, pour pouvoir réclamer avant le relevé (une date peut les cacher si besoin).","Moyennes coupées à deux décimales sans arrondir (13,995 → 13,99), la mention suit la note imprimée (règle du Préfet des études) ; les calculs justes à 10,00 et 14,00 restent justes.","Sauvegarde : la vérification contrôle que chaque relevé archivé et remis est dans la sauvegarde et intact.","Page du code QR des relevés, attestations et cartes : signature du Préfet des études et cachet du Séminaire (copie réduite et marquée), si le Préfet les publie (Administration › Signature).","« Aide » : « Pourquoi ? » à côté des blocages, rappels du calendrier (février, mai, juin-juillet, septembre), lexique, nouvelles fiches ; État du site : contrôle « réglage sans aide » et export Word de toutes les fiches pour la relecture."]},{v:310,d:"2026-11-17",l:["Relevés (bulletins) faits à partir d’un modèle : Administration › Relevés › « 📋 Modèle L1-L2 » et « 📋 Modèle L3 ». Tout se règle : en-tête, colonnes (affichées, nom, ordre : intitulé, enseignant, heures, ECTS, note, mention, crédits), regroupement par semestre ou par discipline, calcul (moyenne simple ou pondérée par les ECTS ou les heures, décimales, note de validation, barème des mentions), textes, observations, absences, appréciation, décision, signatures, police, couleur, marges. Au départ, le relevé est identique à celui d’avant.","L3 : relevé du cycle (L1, L2, L3), moyenne et mention du cycle, mémoire (titre, directeur, note), examens de fin de cycle, total des ECTS, décision du jury, diplôme, signature de l’UCM, rubriques ajoutées ; chaque élément s’affiche ou se masque et se renomme. Le modèle L1-L2 et le modèle L3 sont indépendants.","Garde-fous : aperçu sur de vrais étudiants ; avant d’enregistrer, le nombre de moyennes, mentions et crédits qui changeraient ; historique (qui, quand, quoi) et « Revenir à cette version » ; un relevé archivé garde le modèle de son jour et ne change jamais ; les notes ne se changent que par la saisie des notes. Code QR d’authenticité sur chaque relevé archivé : la page confirme nom, classe, année et moyenne. Il faut le fichier SQL 125."]},{v:309,d:"2026-11-17",l:["Le code QR du site (gstf-faliarivo.ovh) est maintenant sur tous les documents : tout ce qui s’imprime ou s’enregistre en PDF depuis le site (relevés, bulletins, listes, emplois du temps, livret des cours…), les fichiers Word (lettres, actes, livret, rapports), le livret académique (dernière page), le dos de sa couverture (réglable), les actes et le dépliant du symposium. Les lettres et attestations numérotées gardent leur code QR d’authenticité."]},{v:308,d:"2026-11-17",l:["Administration › Livret académique › « 📘 Fabriquer le livret » : le site fabrique tout le livret, au format A5. Au départ, les parties et l’ordre du livret 2026-2027 (calendrier, présentation, théologie, visée, admission, notes disciplinaires, contacts, équipe formatrice, foyers, corps enseignant, étudiants, emplois du temps, cours de chaque année et semestre, volume horaire, table des matières).","Tout est réglable par le responsable : chaque partie peut être affichée ou masquée, montée ou descendue, renommée, modifiée ; « ＋ Ajouter une partie » (texte, image, tableau, saut de page…). Les parties tirées du site (calendrier, équipe, enseignants, étudiants, emplois du temps, syllabus, volume horaire) suivent le site ; « ✏️ Modifier à la main » en fait un texte à soi, « ↻ Revenir aux données du site » les y ramène. Mise en page : police, tailles, interligne, marges, numéros de page, titre en haut des pages, couleur des titres.","Sorties : PDF A5 avec la couverture, table des matières avec les numéros de page, pages blanches pour un multiple de 4 ; « Livret plié » sur feuilles A4 ; version publique sans les noms ni les téléphones ; fichier Word pour retoucher. Les réglages sont gardés d’une année à l’autre et ne sont jamais lisibles par les visiteurs."]},{v:307,d:"2026-11-17",l:["Administration › Livret académique : « 🎨 Couverture du livret », recto (page 1) et dos (page 4) au format A5. Au départ, la forme du livret 2026-2027 ; tout est réglable par le responsable (texte du Séminaire, logo, image de droite, lignes sous le titre, photos, titre, année, police, couleur, taille, texte du dos, BP, téléphone, courriel, site, icônes, marges), et les réglages sont gardés d’une année à l’autre.","Photo du dos (et du recto) : cadre de recadrage au format exact, avertissement « Photo trop petite pour l’impression » sous 1 750 pixels de large, envoi en pleine définition. Sans réglage, l’année vient de l’« Année académique » et les coordonnées du pied de page du site.","Impression : deux pages A5, une feuille A4 horizontale (dos à gauche, recto à droite) ou la version imprimeur (3 mm de fond perdu, traits de coupe). Chaque couverture imprimée est archivée par année ; on peut repartir de n’importe quelle année archivée.","« 📚 Assembler le livret complet » : la couverture (PDF) et l’intérieur tiré de Word (PDF) deviennent un seul livret A5, page 1 devant, page 4 derrière, pages blanches ajoutées pour un multiple de 4 ; tout se fait sur l’ordinateur, rien n’est envoyé. Puis l’option « Livret » d’Adobe Reader.","Garde-fous (ils avertissent sans bloquer) : image trop petite pour sa taille imprimée (300 points par pouce), texte du Séminaire de plus de 3 lignes ou adresse qui sort de la page, couleur du titre trop claire, titre trop petit ; marges jamais sous 5 mm ; « 🔍 Aperçu au format réel »."]},{v:306,d:"2026-11-17",l:["« Aide » cherche partout : la même question trouve aussi les articles, homélies, méditations, l’agenda, les livres et les cours (et les étudiants, pour l’administration). Exemple : « Où est l’article sur Lc 18 ? » mène directement à l’article.","« Aide » parle le premier, une fois par jour au plus : à l’administration (« Examens dans 8 jours : 12 cours n’ont pas encore toutes leurs notes », livres en retard, essai de sauvegarde du trimestre), au bibliothécaire (livres en retard).","« Quoi de neuf ? » : à la première ouverture de « Aide » après une mise à jour, les 3 changements qui vous concernent."]},{v:305,d:"2026-11-17",l:["« Aide » regarde pour de vrai : à « Y a-t-il des notes manquantes ? », « des demandes en attente ? », « des messages sans réponse ? », « des livres en retard ? », « qu’est-ce qui m’attend aujourd’hui ? »…, il répond avec les chiffres du moment (comme le tableau de bord), avec un bouton pour y aller. Réservé à l’administration (au bibliothécaire pour les livres).","« Aide » vérifie lui-même quand on signale un problème : version du téléphone, page pas centrée (zoom, élément qui dépasse), notifications, Internet, langue des lectures, connexion ; il propose le bon bouton.","« Signaler un problème » et « Envoyer le diagnostic » (en bas de « Aide ») : un numéro de suivi, puis « corrigé dans la version … ». Plus besoin de captures d’écran.","Administration : « Aide » connaît aussi tout le dossier de passation (comptes, mise à jour, sauvegardes, pannes, entretien), lu dans une table protégée : jamais visible des visiteurs ni des étudiants.","« Aide » propose les questions les plus posées sur la page ouverte ; la fenêtre du saint et la carte « Liturgie du jour » sont traduites (anglais, italien). Au plus 30 questions par minute ; les traces des questions (sans nom) sont effacées après 6 mois. Il faut les fichiers SQL 123 et 124."]},{v:304,d:"2026-11-17",l:["Téléphone : avec les grands caractères du téléphone, la barre « Partager » ne faisait plus tenir la page dans l’écran ; la page devenait plus large et les fenêtres (« Saint du jour », etc.) se décalaient vers la droite. Elle passe maintenant à la ligne, et les fenêtres se placent toujours au milieu de la partie visible de l’écran.","Articles et méditations programmés (date future) : ils paraissent maintenant seuls ce jour-là à 0 h 01, heure de Madagascar (avant : 6 h) ; la notification et les emails partent dans les 5 minutes ; Facebook, s’il est activé, garde ses heures (de 6 h à 21 h).","Le soir après 18 h (heure de Madagascar), la fenêtre du saint s’intitule « Saint de demain », puisqu’elle montre déjà le lendemain ; la liste des homélies ne dépasse plus sur les écrans très étroits.","Fenêtre du saint : la case « Toujours afficher à l’ouverture » est maintenant à la fin du texte (elle ne prend plus de place en bas de l’écran du téléphone).","Aide : à la question « Y a-t-il des notes manquantes ? », il regarde maintenant pour de vrai et répond avec les chiffres du moment (cours, classe, professeur, notes saisies), comme le tableau de bord ; il sait aussi répondre « la page n’est pas centrée sur mon téléphone »."]},{v:303,d:"2026-11-17",l:["Vitesse : les réponses de « Aide » (environ 270 Ko) ne sont plus téléchargées à chaque ouverture du site, mais seulement quand on ouvre « Aide » ou qu’on fait une recherche. Le programme du site devient environ 20 % plus léger."]},{v:302,d:"2026-11-16",l:["Mises à jour : à l’ouverture, si une version plus récente est en ligne, le site se recharge tout seul une fois. Les téléphones ne restent plus sur l’ancienne version (fenêtre « Saint du jour » décalée, etc.).","Administration : la « Scolarité » est rangée en trois groupes, par personne concernée : « Étudiants » (étudiants, demandes, nouvelle inscription, étudiants à suivre, cartes), « Professeurs » (enseignants, emploi du temps, évaluation des cours, conseil des formateurs) et « Notes et documents » (relevés, corrections demandées, historique des notes, plagiat, livret académique, année académique).","Vitesse : à l’ouverture, le site reçoit l’essentiel de l’accueil en un seul appel (réglages, cours, annonces, actualités, articles, homélies, agenda, intentions, chiffres) au lieu d’une quinzaine. Il faut le fichier SQL 122 ; sans lui, le site fonctionne comme avant."]},{v:301,d:"2026-11-16",l:["Imprimer ou PDF (bulletins, relevés, attestations, livret…) : avant la fenêtre d’impression, une petite fenêtre explique comment obtenir un fichier PDF (à la ligne « Imprimante », choisir « Enregistrer au format PDF »). Case « Je sais faire » pour ne plus la voir.","Bibliothèque : le début du résumé s’affiche directement dans la liste des livres (📖)."]},{v:300,d:"2026-11-16",l:["Le bouton d’aide s’appelle simplement « Aide ». Il répond pendant que vous écrivez, on peut dicter sa question (🎤) et écouter la réponse (🔊). En l’ouvrant : « 📍 Sur cette page » (les réponses pour la page où vous êtes) et « 🛠 Résoudre un problème » (25 pannes et leurs solutions : mise à jour qui ne passe pas, zip déposé par erreur, vidéo qui ne s’affiche pas, méditation introuvable, date décalée, Google Authenticator, connexion, numéro faux, tâches automatiques…).","Un article programmé paraît à 6 h, heure de Madagascar, même s’il a été écrit depuis l’Europe (avant : 8 h à Madagascar pour un texte programmé depuis l’Italie).","Aide : fiches mises à jour (homélies, méditations, intention, dons, dates) et trois nouvelles : ranger un article dans une autre rubrique, retirer un élément, pourquoi l’heure de Madagascar."]},{v:299,d:"2026-11-16",l:["Homélies : sur le site, dans l’Administration et sur les pages pour Google, chaque homélie porte le même titre (le dimanche et sa date) et il n’y en a qu’une par dimanche (une vidéo mal datée par la chaîne reçoit le dimanche de sa mise en ligne). Administration › Homélies : « 🙈 Masquer » sous chaque vidéo.","Application : le raccourci « Confier une intention de prière » ouvre directement le formulaire (le Saint du jour ne s’ouvre plus par-dessus quand l’application est lancée par un raccourci).","Soutenir le Séminaire : tant qu’aucun moyen de don n’est publié, la page invite à contacter l’économat (avec son numéro), au lieu de « coordonnées bientôt publiées ».","Anciens : tant que la liste est vide, un message invite les anciens à se faire connaître. Carte d’étudiant : une phrase explique comment vérifier une carte. Archives des bulletins : un seul titre pour les visiteurs."]},{v:298,d:"2026-11-16",l:["Administration › Méditations : en bas, les textes qui ressemblent à des méditations mais sont rangés ailleurs (titre « Méditation » dans Homélies, ou début « Chers frères et sœurs » dans Articles), avec « 📂 Ranger dans Méditations » (un par un ou tous).","Articles, Homélies, Méditations, Photos et Actualités ont les mêmes boutons : écrire ou ajouter, 👁 voir, ✏️ modifier, 📂 ranger dans une autre rubrique (articles), 🌍/🎓 choisir qui peut lire, 🗑 retirer (avec confirmation). Photos : aussi ☆ Inoubliable."]},{v:297,d:"2026-11-16",l:["Dates des articles, homélies et méditations : elles sont toujours données à l’heure de Madagascar. Avant, un lecteur en Europe voyait la veille pour un texte publié tard le soir ou après minuit à Madagascar (ex. la méditation du lundi 16 novembre affichée « 15 novembre »). Les pages d’articles pour Google sont corrigées de la même façon."]},{v:296,d:"2026-11-16",l:["Administration : « Actualités et photos » est séparé en quatre rubriques : « Actualités », « Photos » (tous les albums, avec ＋ / − Photos), « Homélies » (l’homélie vidéo du dimanche et les homélies écrites) et « Méditations ». Chacune a son bouton pour écrire ou ajouter. Rien ne change pour les visiteurs ni dans la base de données."]},{v:295,d:"2026-11-16",l:["Téléphone : la fenêtre « Saint du jour » (et les autres fenêtres du même type) s’ouvre toujours au centre de l’écran. Sur certains téléphones, elle apparaissait décalée vers la droite et vers le bas, avec le bouton › et le bas coupés."]},{v:294,d:"2026-11-16",l:["Accueil : plus aucune écriture sur la grande photo (ni nom, ni légende) ; les boutons « 🎓 Devenir séminariste » et « ❤️ Soutenir le Séminaire » sont placés juste en dessous de la photo. Le nom du Séminaire reste en haut de la page."]},{v:293,d:"2026-11-16",l:["Connexion : dans les portails Professeur et Éducateurs, le site demande l’identifiant complet (…@gstf-faliarivo.ovh). Avant, en écrivant seulement un nom porté par plusieurs personnes (ex. un étudiant et un responsable), la connexion échouait sans explication claire. Le portail Étudiant garde la connexion par le nom ou le téléphone."]},{v:292,d:"2026-11-16",l:["Contact : le numéro public du secrétariat et du bouton WhatsApp est désormais le numéro du Séminaire (+261 38 21 220 21), et non plus un numéro personnel. Si le champ WhatsApp est vide dans « Modifier les coordonnées », le bouton WhatsApp n’apparaît pas.","« Aide » comprend mieux : on peut poser sa question en anglais ou en italien (« How do I log in? », « Dove si trova il seminario? »), avec plusieurs centaines de mots et synonymes en plus, et des tournures entières (« je n’arrive pas à me connecter », « où se trouve le séminaire »…). Les réponses restent celles du site : rien n’est inventé.","Téléphone : en-tête moins haut (surtout sur les téléphones réglés en grande taille) ; les flèches ‹ › disparaissent sur téléphone (le téléphone a son bouton retour) ; « Mon espace » tient sur une ligne dans la barre du bas ; bouton « ? » un peu plus petit."]},{v:291,d:"2026-11-16",l:["Administration, après un audit de toutes les rubriques : le Tableau de bord ne provoque plus d’erreur à chaque clic ; retirer un bibliothécaire ou un livre d’une bibliographie demande confirmation ; si l’enregistrement des rédacteurs d’un groupe échoue, les anciens sont gardés ; une inscription acceptée dont la demande n’a pas pu être marquée le signale ; si l’enregistrement de l’emploi du temps échoue, l’ancienne version de la semaine est remise.","Téléphone : « État du site » (tableau de la vitesse), « Facebook et YouTube » et « Évaluation » ne débordent plus."]},{v:290,d:"2026-11-16",l:["Téléphone : les textes ne sont plus justifiés sur les écrans étroits (fini les grands blancs entre les mots) ; dans un article, la couverture se met en petit à côté du titre, et le bouton « ⤴ Autre » dit ce qu’il fait."]},{v:289,d:"2026-11-16",l:["Téléphone : la fenêtre « Recevez gratuitement nos nouveaux articles » n’apparaît plus qu’après 40 secondes de lecture d’un article, une fois, et jamais sur Contact, Inscription ou pendant qu’on remplit un formulaire.","Téléphone : les champs des formulaires ne font plus zoomer l’iPhone ; cases à cocher, liens et points du diaporama plus faciles à toucher ; plus de texte de moins de 12 pixels."]},{v:288,d:"2026-11-16",l:["Études, sur téléphone : le plan d’études n’est plus un grand tableau coupé ; il s’affiche en liste, un semestre à la fois (touchez le semestre pour l’ouvrir)."]},{v:287,d:"2026-11-16",l:["Contact : le plan d’accès est une image fixe, légère, qui s’affiche même en 3G ; un clic ouvre Google Maps. Le bouton WhatsApp dit « WhatsApp du secrétariat » et montre le numéro. Le bouton « Aide » se réduit à un rond « ? » sur la page Contact et dès qu’on remplit un formulaire.","Les visiteurs non connectés ne voient plus le menu « Espace du Séminaire » ; Prières, Événements inoubliables, Anciens et Rendez-vous sont dans le pied de page."]},{v:286,d:"2026-11-16",l:["Bibliothèque : le compteur public n’affiche plus de zéros (« 0 en prêt ») ; sans horaires remplis, le public lit « demandez au secrétariat » ; le bouton « Emprunter » précise qu’aucun compte n’est nécessaire.","Menu « Espace du Séminaire » : un visiteur ne voit plus Administration, Archives ni Économat."]},{v:285,d:"2026-11-16",l:["Passage à l’année suivante (avec le SQL 120) : les vraies dates de la nouvelle année se choisissent au moment du passage ; les sortants peuvent être ajoutés à « Anciens » en un clic ; les notes et présences de l’année sont gardées (consultables en bas de la page « Année académique ») au lieu d’être effacées.","Correction importante : le passage aurait été refusé à cause des numéros de classe (deux étudiants avec le même numéro dans une classe) ; les 2e et 3e années sont maintenant renumérotées par ordre alphabétique.","Bibliothèque (fonction v65) : quand Google Livres est saturé, la recherche automatique des résumés et couvertures ne s’arrête plus : elle continue avec Open Library et Wikipédia."]},{v:284,d:"2026-11-16",l:["Année académique : bouton « 🔍 Simulation (ne change rien) » avant le passage à l’année suivante : effectifs de chaque classe après le passage, liste des sortants, et vérifications (bulletins archivés, sauvegarde récente, notes et présences qui seront effacées)."]},{v:283,d:"2026-11-16",l:["Google et partage : chaque article public a sa propre page (gstf-faliarivo.ovh/articles/…), avec son titre, son résumé et son image ; les homélies en vidéo aussi. Les boutons WhatsApp et Facebook partagent cette page : vos contacts voient la carte de l’article, et non plus celle du Séminaire. Pages préparées chaque heure par GitHub ; plan du site pour Google (sitemap-articles.xml).","Un seul titre principal sur le site (le nom du Séminaire) : chaque page a son titre juste en dessous, comme Google le préfère."]},{v:282,d:"2026-11-16",l:["Vitesse de l’accueil, surtout en 3G : les réglages sont lus en une seule fois (avant : 21 demandes séparées) ; articles et homélies ne sont plus lus plusieurs fois ; les syllabus (190 Ko) ne sont plus chargés pour les simples visiteurs ; une police en moins.","Logo : une petite version (≈ 10 Ko au lieu de 400 Ko) s’affiche à l’écran ; la grande reste pour les bulletins et fiches imprimés. La grande photo d’accueil s’affiche en version téléphone sur les petits écrans.","Apparence : bouton « Préparer les versions légères » pour les anciennes images (logo, photo d’accueil, bandeau, « Notre histoire »)."]},{v:281,d:"2026-11-16",l:["Sécurité (avec le SQL 119) : la connexion par nom, par téléphone ou par adresse personnelle est réservée aux étudiants ; professeurs, équipe et administration se connectent avec leur identifiant complet (…@gstf-faliarivo.ovh). La liste des bibliothécaires n’est plus lisible que par l’administration ; les réglages internes (état de la sauvegarde, historique du tableau de bord, livret…) ne sont plus lisibles par les visiteurs.","État du site : nouveau « 🔒 Test réel : que voit un visiteur non connecté ? », qui essaie de lire chaque table et chaque espace de fichiers sans connexion."]},{v:280,d:"2026-11-16",l:["Accueil : à la fin de la page, un dernier cadre « Rejoindre · Soutenir » avec les boutons « 🎓 Devenir séminariste » et « ❤️ Soutenir le Séminaire » (ils restent aussi sur la photo, en haut). On peut le déplacer ou le masquer dans Apparence › Blocs de la page d’accueil."]},{v:279,d:"2026-11-16",l:["Saint du jour (fenêtre « Jour passé / Jour à venir ») : sur un téléphone étroit, les boutons ‹ Aujourd’hui › passent sous le titre au lieu de l’écraser lettre par lettre ; « Couleur liturgique : blanche » se lit maintenant (avant : blanc sur blanc)."]},{v:278,d:"2026-11-16",l:["Agenda personnel (avec le SQL 118) : chaque personne connectée note ses propres rendez-vous ; personne d’autre ne les voit. Le plus proche s’affiche à l’accueil, dans le cadre « 📅 Mon agenda », entre « Dernière annonce » et « Bibliothèque ». Aussi dans l’onglet « Agenda » › « 📅 Mon agenda personnel »."]},{v:277,d:"2026-11-15",l:["Articles : nouveau champ « 📅 Date de l’article ». Une date passée date l’article ; une date future le programme : il reste caché et paraît seul ce jour-là à 6 h, avec sa notification, ses emails et sa publication Facebook (avec le SQL 117 et la fonction v63)."]},{v:276,d:"2026-11-15",l:["Administration › « 📘 Livret académique » : le livret de l’année suivante, préparé chaque année (2027-2028 pour commencer), avec ses échéances (impression : 2 mois), neuf parties à valider et les tableaux prêts à copier dans Word (équipe, enseignants, effectifs).","Le tableau de bord rappelle l’étape suivante du livret ; tout est noté (qui, quand) pour la passation.","« Aide » complété : premiers pas pour chaque rôle (visiteur, étudiant, professeur, éducateur, administration), conseils pour les fonctions délicates, et des fiches pour le calendrier, le volume horaire, le règlement, le corps enseignant, les archives, les événements inoubliables, la confidentialité, les questions de révision et les annales (côté professeur).","Confidentialité : texte mis à jour sur l’annuaire (coordonnées des étudiants visibles des autres étudiants seulement avec leur accord)."]},{v:275,d:"2026-11-15",l:["Vitesse sur téléphone (84 % des visites) : en 2G ou en « économie de données », le site s’allège tout seul ; l’application installée ne garde plus son écran d’ouverture plus de 2,5 s ; la bibliothèque de connexion est gardée sur le téléphone.","État du site : nouvelle mesure détaillée, « page visible » et « site prêt », première visite ou visite suivante, pour suivre l’objectif : 3G sous les 3 secondes.","« Aide » : que faire si Supabase met le projet en pause (vacances d’août)."]},{v:274,d:"2026-11-15",l:["Sauvegarde : après « Connecter Google Drive », retour direct sur le site avec un message clair ; textes de la page mis à jour pour la sauvegarde automatique.","État du site : contrôle des fichiers SQL jusqu’au 115 et des deux tâches de la sauvegarde Google Drive.","Tableau de bord : la ligne des notes à saisir reste bleue (à suivre) jusqu’au début des examens, avec leur date."]},{v:273,d:"2026-11-15",l:["Sauvegarde Google Drive : nouveau bouton « 🔗 Connecter Google Drive » dans Administration › Sauvegarde. Plus besoin de l’outil de Google ni de copier un code : on clique, on choisit le compte du Séminaire, c’est fait."]},{v:272,d:"2026-11-15",l:["Sauvegarde automatique sur le Google Drive du Séminaire : toutes les données chaque dimanche, les photos et PDF chaque nuit ; on garde 8 semaines, puis une par mois pendant un an.","Administration › Sauvegarde : l’état de la sauvegarde Drive, le lien vers le dossier et deux boutons pour envoyer tout de suite ; le tableau de bord signale une erreur ou un retard.","« Aide » : la sauvegarde Drive, que faire en cas d’erreur, et l’ancien hébergement Netlify (résilié)."]},{v:271,d:"2026-11-15",l:["« Aide » : tout sur la sauvegarde, la vérification (restauration d’essai) pas à pas, l’offre gratuite de Supabase, la règle 3-2-1, les photos et PDF, et comment le site est construit."]},{v:270,d:"2026-11-15",l:["Tableau de bord : « À faire aujourd’hui », trié par urgence (rouge, orange, bleu), avec un bouton d’action et un « ? » sur chaque ligne ; les zéros sont repliés en une ligne.","Une vue par responsable (Recteur, Préfet des études, Secrétariat, Économe), barres d’avancement (cartes, notes, adresses) avec leur évolution, et la date de la sauvegarde vérifiée.","Notes à saisir en tableau sur toute la largeur, avec « Relancer par WhatsApp » ; prochains événements de l’agenda complets ; résumé du matin par WhatsApp et email (fonction v59)."]},{v:269,d:"2026-11-15",l:["Contact plus court : l’annuaire devient une page à part (« Annuaire », dans l’Espace du Séminaire), qui montre d’abord l’équipe et les professeurs.","Vie privée : le téléphone et l’email d’un étudiant ne sont montrés aux autres étudiants que s’il l’accepte (Mes coordonnées) ; numéros écrits partout +261 34 92 920 77.","Formulaire : « Choisissez… » l’objet, qui va à la bonne personne ; case d’accord ; horaires en direct (« Fermé · ouvre lundi à 8 h ») ; messe et visites ; carte Google de secours."]},{v:268,d:"2026-11-15",l:["Articles : le dernier texte en grand, puis les autres par mois ; temps de lecture, bouton « WhatsApp » et un seul bouton « Lire » ; couvertures de couleurs différentes selon la rubrique.","Le livret et la méthodologie passent dans Études › Documents officiels ; les guides du site dans « Aide ».","Badge de langue (malagasy…), invitation à écrire pour les membres ; pour l’administration : le rythme de publication et « 🧹 Vérifier la page » (titres trop généraux, rubriques, écriture)."]},{v:267,d:"2026-11-15",l:["Agenda : « Aujourd’hui », puis « Cette semaine », puis les 30 prochains jours (« Voir toute l’année ») ; l’abonnement du téléphone juste sous les filtres.","Fêtes ajoutées (Sainte Famille, Épiphanie, Baptême, Présentation, Trinité, Saint-Sacrement) avec leur couleur liturgique et leur rang ; Saint Jacques Berthieu ; Ascension séparée de l’excursion ; compte à rebours.","Administration : tout dans « Gérer l’agenda », vérification annuelle des fêtes, rappel des photos à publier, événement relié à un article."]},{v:266,d:"2026-11-15",l:["Bibliothèque : la recherche en haut, puis mes emprunts (dates en couleur), la bibliothèque numérique et les infos pratiques ; la gestion est à part, pour le bibliothécaire.","Fiche du livre (cote, emplacement, cours qui l’utilisent) et « Tous les livres de mes cours ».","Étiquettes QR à coller dans les livres, prêt et retour avec le téléphone, nettoyage du catalogue (sur place, doublons, Excel)."]},{v:265,d:"2026-11-15",l:["Études › Syllabus : « Le programme en bref », plan d’études (par année ou par discipline), filtres « Mes cours » et « Fiches incomplètes », cours rangés par ordre alphabétique.","Un même état des fiches partout : Pas de fiche, Incomplète (n/4), Complète ; outils du professeur sur sa fiche (à compléter, vérifier la bibliographie).","Réglages du programme décidés par le conseil des professeurs : crédits ECTS, institution du diplôme, plan par discipline."]},{v:264,d:"2026-11-15",l:["Portail Professeur en onglets : Appel et notes d’abord, puis Devoirs, Documents, Syllabus et bibliographie, Plagiat, Absences, Mon compte.","Appel en un clic (P, A, R pour retard, E), observation, note contrôlée à la frappe, Entrée pour l’étudiant suivant, enregistrement automatique même hors connexion.","Séance choisie dans l’emploi du temps ; valider et verrouiller les notes (déverrouillage par le Préfet des études) ; feuille d’émargement en PDF ; notes en Excel.","Fiches d’étudiants en double : les trouver et les réunir sans rien perdre."]},{v:261,d:"2026-11-15",l:["« Aide » comprend mieux : fautes de frappe corrigées (« J’ai compris : … »), synonymes.","Les réponses de la page où vous êtes passent en premier ; « Vouliez-vous dire… ? » quand la question est floue.","Poser sa question au secrétariat directement depuis l’aide (réponse par email)."]},{v:260,d:"2026-11-15",l:["Apparence : titre et sous-titre du bandeau en français, anglais et italien (badge « à traduire »), réglage du voile sombre de la photo.","Liseré de la couleur liturgique du jour, vérification de la lisibilité des couleurs, logo pour fond sombre.","Blocs de l’accueil à afficher, masquer ou réordonner ; programmation par dates ; aperçu Téléphone et Ordinateur ; historique avec « Restaurer »."]},{v:259,d:"2026-11-15",l:["Accueil : le nom du Séminaire et les boutons « Devenir séminariste » et « Soutenir le Séminaire » sont posés sur la photo, avec un voile sombre pour bien les lire.","Un badge « Nouveau » signale pendant 30 jours chaque option ajoutée.","Cette page « Quoi de neuf ? », ouverte en cliquant sur le numéro de version en bas de page."]},{v:258,d:"2026-11-15",l:["Menu « Affichage » en haut : calendrier, mode sombre, défilement, taille du texte, connexion faible, installer l’application.","Le bouton « Aide » est en bas à droite.","La page d’accueil ne reste plus jamais vide : tout s’affiche, même sans défiler."]},{v:257,d:"2026-11-15",l:["Conseil des formateurs : évaluation annuelle confidentielle selon les quatre dimensions de la formation, avec l’avis du conseil (réservé au conseil).","Absences des professeurs : signalement, annulation, remplacement, rattrapage, et la classe est prévenue.","Heures faites par cours, pour l’administration et pour chaque professeur."]},{v:256,d:"2026-11-15",l:["Actualités : modifier, aperçu, brouillon, publication programmée, légendes des photos, photo de couverture.","Bilan de « Aide » dans l’État du site."]}]}
